n\nconst useGetSendIcsPreferencesMap = () => {\n    const api = useApi();\n    const getEncryptionPreferences = useGetEncryptionPreferences();\n    const getMailSettings = useGetMailSettings();\n\n    return useCallback(\n        async ({\n            inviteActions,\n            vevent,\n            cancelVevent,\n            contactEmailsMap,\n        }: {\n            inviteActions: InviteActions;\n            vevent?: VcalVeventComponent;\n            cancelVevent?: VcalVeventComponent;\n            contactEmailsMap?: SimpleMap<ContactEmail>;\n        }) => {\n            const { type, addedAttendees, removedAttendees } = inviteActions;\n            const hasAddedAttendees = !!addedAttendees?.length;\n            const hasRemovedAttendees = !!removedAttendees?.length;\n            const invitedEmails = vevent?.attendee?.map((attendee) => getAttendeeEmail(attendee));\n            const addedEmails = addedAttendees?.map((attendee) => getAttendeeEmail(attendee));\n            const removedEmails = removedAttendees?.map((attendee) => getAttendeeEmail(attendee));\n            const cancelledEmails = cancelVevent?.attendee?.map((attendee) => getAttendeeEmail(attendee));\n            const organizerEmail = vevent?.organizer ? getAttendeeEmail(vevent.organizer) : undefined;\n            const emails: string[] = [];\n\n            if (type === SEND_INVITATION) {\n                if (!hasAddedAttendees && !hasRemovedAttendees && invitedEmails?.length) {\n                    emails.push(...invitedEmails);\n                } else {\n                    if (addedEmails?.length) {\n                        emails.push(...addedEmails);\n                    }\n                    if (removedEmails?.length) {\n                        emails.push(...removedEmails);\n                    }\n                }\n            } else if (type === SEND_UPDATE) {\n                if (invitedEmails?.length) {\n                    emails.push(...invitedEmails);\n                }\n                if (removedEmails?.length) {\n                    emails.push(...removedEmails);\n                }\n            } else if (type === CANCEL_INVITATION) {\n                if (cancelledEmails?.length) {\n                    emails.push(...cancelledEmails);\n                }\n            } else if ([CHANGE_PARTSTAT, DECLINE_INVITATION].includes(type)) {\n                if (organizerEmail) {\n                    emails.push(organizerEmail);\n                }\n            }\n\n            const { Sign } = await getMailSettings();\n            const messageWithPreferences = getIcsMessageWithPreferences(Sign);\n\n            const sendPreferencesMap: SimpleMap<SendPreferences> = {};\n            await Promise.all(\n                emails.map(async (email) => {\n                    const encryptionPreferences = await getEncryptionPreferences(email, 0, contactEmailsMap);\n                    const sendPreferences = getSendPreferences(encryptionPreferences, messageWithPreferences);\n                    sendPreferencesMap[email] = sendPreferences;\n                })\n            );\n            return sendPreferencesMap;\n        },\n        [api, getEncryptionPreferences, getMailSettings]\n    );\n};\n\nexport default useGetSendIcsPreferencesMap;\n","import { memo } from 'react';\nimport { isSameDay } from '@proton/shared/lib/date-fns-utc';\n\ninterface Props {\n    days: Date[];\n    now: Date;\n    date: Date;\n    formattedDates: string[];\n    onClickDate: (day: Date) => void;\n}\nconst DayButtons = ({ days, now, date, formattedDates, onClickDate }: Props) => {\n    return (\n        <>\n            {days.map((day, dayIndex) => {\n                return (\n                    <button\n                        type=\"button\"\n                        aria-label={formattedDates[dayIndex]}\n                        className=\"flex-item-fluid text-center calendar-monthgrid-day p0-25\"\n                        key={day.getUTCDate()}\n                        aria-current={isSameDay(day, now) ? 'date' : undefined}\n                        aria-pressed={isSameDay(day, date) ? true : undefined}\n                        onClick={() => onClickDate(day)}\n                    >\n                        <span className=\"calendar-monthgrid-day-number flex mauto\">\n                            <span className=\"mauto\">{day.getUTCDate()}</span>\n                        </span>\n                    </button>\n                );\n            })}\n        </>\n    );\n};\n\nconst MemoedDayButtons = memo(DayButtons);\n\nexport default MemoedDayButtons;\n","import { useMemo, useState, useRef, useLayoutEffect, useEffect, Ref } from 'react';\nimport { chunk } from '@proton/shared/lib/helpers/array';\nimport { eachDayOfInterval, isSameMonth } from '@proton/shared/lib/date-fns-utc';\nimport { getISOWeek } from 'date-fns';\n\nimport useDayGridEventLayout from './useDayGridEventLayout';\nimport createDayGridMouseHandler from './interactions/dayGridMouseHandler';\nimport { useRect } from '../../hooks/useRect';\nimport RowEvents from './DayGrid/RowEvents';\nimport DayButtons from './DayGrid/DayButtons';\nimport { DAY_EVENT_HEIGHT } from './constants';\nimport { CalendarViewEvent, TargetEventData, TargetMoreData } from '../../containers/calendar/interface';\n\ninterface Props {\n    tzid: string;\n    now: Date;\n    date: Date;\n    dateRange: [Date, Date];\n    displayWeekNumbers?: boolean;\n    isInteractionEnabled?: boolean;\n    events: CalendarViewEvent[];\n    targetEventRef: Ref<HTMLDivElement>;\n    targetMoreData?: TargetMoreData;\n    targetMoreRef: Ref<HTMLDivElement>;\n    targetEventData?: TargetEventData;\n    onMouseDown: (a: any) => any /** todo */;\n    formatTime: (date: Date) => string;\n    formatDate: (date: Date) => string;\n    onClickDate: (date: Date) => void;\n    weekdaysLong: string[];\n}\n\nconst DayGrid = ({\n    tzid,\n    now,\n    date,\n    dateRange: [start, end],\n    dateRange,\n    displayWeekNumbers = false,\n    isInteractionEnabled = false,\n    events,\n    targetEventRef,\n    targetMoreRef,\n    targetEventData,\n    targetMoreData,\n    onMouseDown,\n    formatTime,\n    formatDate,\n    onClickDate,\n    weekdaysLong = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],\n}: Props) => {\n    const rowsWrapperRef = useRef<HTMLDivElement>(null);\n    const firstRowRef = useRef<HTMLDivElement>(null);\n    const firstRowRect = useRect(firstRowRef.current);\n    const [numberOfRows, setNumberOfRows] = useState(0);\n\n    const daysInWeek = 7;\n    const dayEventHeight = DAY_EVENT_HEIGHT;\n\n    const rows = useMemo(() => {\n        return chunk(eachDayOfInterval(start, end), daysInWeek);\n    }, [+start, +end]);\n\n    const eventsPerRows = useDayGridEventLayout(rows, events, numberOfRows, dayEventHeight);\n\n    useLayoutEffect(() => {\n        const { height: firstRowHeight = 100 } = firstRowRect || {};\n        const newNumberOfRows = Math.max(Math.floor(firstRowHeight / dayEventHeight), 1);\n        setNumberOfRows(newNumberOfRows - 1);\n    }, [firstRowRect, dateRange]);\n\n    const handleMouseDownRef = useRef<(e: MouseEvent) => void>();\n\n    handleMouseDownRef.current = (e: MouseEvent) => {\n        if (!rowsWrapperRef.current) {\n            return;\n        }\n        createDayGridMouseHandler({\n            e,\n            events,\n            eventsPerRows,\n            rows,\n            dayGridEl: rowsWrapperRef.current,\n            onMouseDown,\n        });\n    };\n\n    useEffect(() => {\n        if (!isInteractionEnabled) {\n            return;\n        }\n        const listener = (e: MouseEvent) => {\n            if (e.button !== 0) {\n                return;\n            }\n            handleMouseDownRef.current?.(e);\n        };\n        document.addEventListener('mousedown', listener, true);\n        return () => {\n            document.removeEventListener('mousedown', listener, true);\n        };\n    }, [isInteractionEnabled]);\n\n    const formattedDates = useMemo(() => {\n        return rows.map((days) => {\n            return days.map(formatDate);\n        });\n    }, [rows, formatDate]);\n\n    return (\n        <div className=\"flex-item-fluid scroll-if-needed h100 is-month-view\">\n            <div className=\"calendar-daygrid flex flex-column relative h100\">\n                <div data-test-id=\"calendar-month-view:week-header\" className=\"flex calendar-daygrid-days\">\n                    {displayWeekNumbers ? <div className=\"calendar-daygrid-weeknumber-width\" /> : null}\n                    {rows[0].map((day) => {\n                        return (\n                            <div\n                                className=\"flex-item-fluid text-center calendar-daygrid-day text-lg m0 p0-75 text-ellipsis\"\n                                key={day.getUTCDate()}\n                                aria-current={\n                                    day.getUTCDay() === now.getUTCDay() && isSameMonth(date, now) ? 'true' : undefined\n                                }\n                            >\n                                <span className=\"calendar-grid-heading-day-fullname text-semibold\">\n                                    {weekdaysLong[day.getUTCDay()]}\n                                </span>\n                                <span\n                                    className=\"calendar-grid-heading-day-shortname no-desktop no-tablet\"\n                                    aria-hidden=\"true\"\n                                >\n                                    {weekdaysLong[day.getUTCDay()][0]}\n                                </span>\n                            </div>\n                        );\n                    })}\n                </div>\n                <div className=\"flex flex-item-fluid\">\n                    {displayWeekNumbers ? (\n                        <div className=\"flex flex-column calendar-daygrid-weeknumber-width\">\n                            {rows.map((days) => {\n                                const monday = days.find((date) => date.getDay() === 1);\n                                if (!monday) {\n                                    return null;\n                                }\n                                const week = getISOWeek(monday);\n                                return (\n                                    <div\n                                        key={+monday}\n                                        className=\"flex-item-fluid flex flex-column flex relative calendar-daygrid-weeknumber\"\n                                    >\n                                        <span className=\"mauto opacity-40 text-sm\">{week}</span>\n                                    </div>\n                                );\n                            })}\n                        </div>\n                    ) : null}\n\n                    <div className=\"flex flex-item-fluid flex-column calendar-daygrid-rows\" ref={rowsWrapperRef}>\n                        {rows.map((days, rowIndex) => {\n                            const { eventsInRow, eventsInRowStyles, eventsInRowSummary } = eventsPerRows[rowIndex];\n\n                            return (\n                                // eslint-disable-next-line react/no-array-index-key\n                                <div key={rowIndex} className=\"flex-item-fluid flex flex-column h100 w100 relative\">\n                                    <div\n                                        data-test-id=\"calendar-month-view:week-row\"\n                                        className=\"flex calendar-daygrid-columns no-pointer-events\"\n                                    >\n                                        {days.map((day) => {\n                                            return (\n                                                <div\n                                                    data-test-id=\"calendar-month-view:day-cell\"\n                                                    className=\"flex-item-fluid calendar-daygrid-column\"\n                                                    key={day.getUTCDate()}\n                                                />\n                                            );\n                                        })}\n                                    </div>\n                                    <div className=\"flex\">\n                                        <DayButtons\n                                            days={days}\n                                            now={now}\n                                            date={date}\n                                            formattedDates={formattedDates[rowIndex]}\n                                            onClickDate={onClickDate}\n                                        />\n                                    </div>\n                                    <div\n                                        className=\"relative flex-item-fluid calendar-daygrid-row\"\n                                        data-row={rowIndex}\n                                        {...(rowIndex === 0 ? { ref: firstRowRef } : undefined)}\n                                    >\n                                        <RowEvents\n                                            tzid={tzid}\n                                            eventsInRowStyles={eventsInRowStyles}\n                                            eventsInRowSummary={eventsInRowSummary}\n                                            eventsInRow={eventsInRow}\n                                            events={events}\n                                            formatTime={formatTime}\n                                            days={days}\n                                            now={now}\n                                            row={rowIndex}\n                                            targetMoreData={targetMoreData}\n                                            targetMoreRef={targetMoreRef}\n                                            targetEventRef={targetEventRef}\n                                            targetEventData={targetEventData}\n                                        />\n                                    </div>\n                                </div>\n                            );\n                        })}\n                    </div>\n                </div>\n            </div>\n        </div>\n    );\n};\n\nexport default DayGrid;\n","import { Ref, RefObject } from 'react';\n\nimport { VIEWS } from '@proton/shared/lib/calendar/constants';\n\nimport TimeGrid from '../../components/calendar/TimeGrid';\nimport DayGrid from '../../components/calendar/DayGrid';\nimport { SharedViewProps, TargetEventData, TargetMoreData, TimeGridRef } from './interface';\nimport { OnMouseDown } from '../../components/calendar/interactions/interface';\n\nconst { DAY, WEEK, MONTH } = VIEWS;\n\ninterface Props extends SharedViewProps {\n    isInteractionEnabled?: boolean;\n    onMouseDown: OnMouseDown;\n    targetEventData?: TargetEventData;\n    targetEventRef: Ref<HTMLDivElement>;\n    targetMoreData?: TargetMoreData;\n    targetMoreRef: Ref<HTMLDivElement>;\n    isScrollDisabled: boolean;\n    timeGridViewRef: RefObject<TimeGridRef>;\n    weekdays: string[];\n    formatTime: (date: Date) => string;\n    formatDate: (date: Date) => string;\n}\nconst CalendarView = ({\n    view,\n    isNarrow,\n\n    isInteractionEnabled,\n    onMouseDown,\n\n    tzid,\n    primaryTimezone,\n    secondaryTimezone,\n    secondaryTimezoneOffset,\n\n    targetEventData,\n    targetEventRef,\n    targetMoreData,\n    targetMoreRef,\n\n    displayWeekNumbers,\n    displaySecondaryTimezone,\n\n    now,\n    date,\n    dateRange,\n    events,\n\n    onClickDate,\n    timeGridViewRef,\n    isScrollDisabled,\n\n    weekdays,\n    formatTime,\n    formatDate,\n}: Props) => {\n    if (view === DAY || view === WEEK) {\n        return (\n            <TimeGrid\n                isNarrow={isNarrow}\n                tzid={tzid}\n                primaryTimezone={primaryTimezone}\n                secondaryTimezone={secondaryTimezone}\n                secondaryTimezoneOffset={secondaryTimezoneOffset}\n                isInteractionEnabled={isInteractionEnabled}\n                isScrollDisabled={isScrollDisabled}\n                onMouseDown={onMouseDown}\n                targetEventData={targetEventData}\n                targetEventRef={targetEventRef}\n                targetMoreRef={targetMoreRef}\n                targetMoreData={targetMoreData}\n                displaySecondaryTimezone={displaySecondaryTimezone}\n                now={now}\n                date={date}\n                dateRange={dateRange}\n                events={events}\n                formatTime={formatTime}\n                onClickDate={onClickDate}\n                actionRef={timeGridViewRef}\n                weekdays={weekdays}\n            />\n        );\n    }\n    if (view === MONTH) {\n        return (\n            <DayGrid\n                tzid={tzid}\n                isInteractionEnabled={isInteractionEnabled}\n                onMouseDown={onMouseDown}\n                targetEventData={targetEventData}\n                targetEventRef={targetEventRef}\n                targetMoreData={targetMoreData}\n                targetMoreRef={targetMoreRef}\n                displayWeekNumbers={displayWeekNumbers}\n                date={date}\n                dateRange={dateRange}\n                now={now}\n                events={events}\n                formatTime={formatTime}\n                formatDate={formatDate}\n                onClickDate={onClickDate}\n                weekdaysLong={weekdays}\n            />\n        );\n    }\n    return null;\n};\n\nexport default CalendarView;\n","import { getAttendeeEmail } from '@proton/shared/lib/calendar/attendees';\nimport { reformatApiErrorMessage } from '@proton/shared/lib/calendar/helper';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar';\nimport { SendPreferences } from '@proton/shared/lib/interfaces/mail/crypto';\nimport { SimpleMap } from '@proton/shared/lib/interfaces/utils';\nimport * as React from 'react';\nimport { Button, BasicModal } from '@proton/components';\nimport { c } from 'ttag';\nimport { CleanSendIcsActionData, INVITE_ACTION_TYPES, InviteActions } from '../../../interfaces/Invite';\n\nconst { SEND_INVITATION, SEND_UPDATE, CHANGE_PARTSTAT, DECLINE_INVITATION, CANCEL_INVITATION, NONE } =\n    INVITE_ACTION_TYPES;\n\nconst getCleanSendData = ({\n    emailsWithError,\n    sendPreferencesMap,\n    inviteActions,\n    vevent,\n    cancelVevent,\n}: {\n    sendPreferencesMap: SimpleMap<SendPreferences>;\n    inviteActions: InviteActions;\n    vevent?: VcalVeventComponent;\n    cancelVevent?: VcalVeventComponent;\n    emailsWithError: string[];\n}) => {\n    const { type, addedAttendees = [], removedAttendees = [] } = inviteActions;\n    const hasAddedAttendees = !!addedAttendees.length;\n    const hasRemovedAttendees = !!removedAttendees.length;\n    const addedCleanAttendees = addedAttendees.filter(\n        (attendee) => !emailsWithError.includes(getAttendeeEmail(attendee))\n    );\n    const invitedEmails = (vevent?.attendee || []).map((attendee) => getAttendeeEmail(attendee));\n    const addedEmails = addedAttendees.map((attendee) => getAttendeeEmail(attendee));\n    const addedEmailsWithError = addedEmails.filter((email) => emailsWithError.includes(email));\n    const existingEmails = invitedEmails.filter((email) => !addedEmails.includes(email));\n    const removedCleanAttendees = removedAttendees.filter(\n        (attendee) => !emailsWithError.includes(getAttendeeEmail(attendee))\n    );\n    const removedEmails = removedAttendees.map((attendee) => getAttendeeEmail(attendee));\n    const removedEmailsWithError = removedEmails.filter((email) => emailsWithError.includes(email));\n    const invitedCleanAttendees = vevent?.attendee?.filter(\n        (attendee) => !emailsWithError.includes(getAttendeeEmail(attendee))\n    );\n    const invitedCleanOfAddedAttendees = vevent?.attendee?.filter((attendee) => {\n        const email = getAttendeeEmail(attendee);\n        return existingEmails.includes(email) || !emailsWithError.includes(email);\n    });\n    const invitedEmailsWithError = (vevent?.attendee || [])\n        .map((attendee) => getAttendeeEmail(attendee))\n        .filter((email) => emailsWithError.includes(email));\n    const cancelledCleanAttendees = cancelVevent?.attendee?.filter(\n        (attendee) => !emailsWithError.includes(getAttendeeEmail(attendee))\n    );\n    const cancelledEmailsWithError = (cancelVevent?.attendee || [])\n        .map((attendee) => getAttendeeEmail(attendee))\n        .filter((email) => emailsWithError.includes(email));\n    const organizerEmail = vevent?.organizer ? getAttendeeEmail(vevent.organizer) : undefined;\n    const organizerEmailWithError =\n        organizerEmail && emailsWithError.includes(organizerEmail) ? organizerEmail : undefined;\n\n    const cleanData = {\n        inviteActions: {\n            ...inviteActions,\n            addedAttendees: addedCleanAttendees,\n        },\n        vevent: vevent\n            ? {\n                  ...vevent,\n                  attendee: invitedCleanOfAddedAttendees || [],\n              }\n            : undefined,\n        cancelVevent,\n        sendPreferencesMap,\n        emailsWithError: [],\n    };\n\n    if (type === SEND_INVITATION) {\n        if (!vevent) {\n            throw new Error('Cannot create event without vevent component');\n        }\n        if (!hasAddedAttendees && !hasRemovedAttendees) {\n            // it's a new invitation\n            return {\n                ...cleanData,\n                vevent: {\n                    ...vevent,\n                    attendee: invitedCleanAttendees,\n                },\n                inviteActions: {\n                    ...cleanData.inviteActions,\n                    type: invitedCleanAttendees?.length\n                        ? INVITE_ACTION_TYPES.SEND_INVITATION\n                        : INVITE_ACTION_TYPES.NONE,\n                },\n                emailsWithError: invitedEmailsWithError,\n            };\n        }\n        // the event exists already\n        const hasAddedOrRemoved = addedCleanAttendees.length || removedCleanAttendees.length;\n        return {\n            ...cleanData,\n            inviteActions: {\n                ...cleanData.inviteActions,\n                type: hasAddedOrRemoved ? SEND_INVITATION : NONE,\n            },\n            emailsWithError: [...addedEmailsWithError, ...removedEmailsWithError],\n        };\n    }\n    if (type === SEND_UPDATE) {\n        const cannotNotify = !invitedCleanAttendees?.length && !removedCleanAttendees?.length;\n        return {\n            ...cleanData,\n            inviteActions: {\n                ...cleanData.inviteActions,\n                type: cannotNotify ? NONE : SEND_UPDATE,\n            },\n            emailsWithError: [...invitedEmailsWithError, ...addedEmailsWithError, ...removedEmailsWithError],\n        };\n    }\n    if (type === CANCEL_INVITATION) {\n        return {\n            ...cleanData,\n            inviteActions: {\n                ...cleanData.inviteActions,\n                type: cancelledCleanAttendees?.length ? CANCEL_INVITATION : NONE,\n            },\n            emailsWithError: cancelledEmailsWithError,\n        };\n    }\n    if ([CHANGE_PARTSTAT, DECLINE_INVITATION].includes(type)) {\n        return {\n            sendPreferencesMap,\n            inviteActions: {\n                ...inviteActions,\n                type: NONE,\n            },\n            vevent,\n            cancelVevent,\n            emailsWithError: [organizerEmailWithError],\n        };\n    }\n    return cleanData;\n};\n\nconst getModalContent = (\n    newInviteActions: InviteActions,\n    originalInviteActions: InviteActions,\n    onClose: () => void,\n    onSubmit: () => void\n): {\n    title: string;\n    warningText: string;\n    alertText?: string;\n    submit?: React.ReactNode;\n    close?: React.ReactNode;\n} => {\n    if (originalInviteActions.type === CHANGE_PARTSTAT) {\n        if (originalInviteActions.isProtonProtonInvite) {\n            // For Proton-Proton invites the answer was changed before sending the email\n            return {\n                title: c('Title').t`Organizer cannot be notified`,\n                warningText: c('Info').t`The organizer could not be notified that you changed your answer:`,\n                close: <Button className=\"mlauto\" color=\"norm\" onClick={onClose}>{c('Action').t`OK`}</Button>,\n            };\n        }\n        return {\n            title: c('Title').t`Organizer cannot be notified`,\n            warningText: c('Info').t`The organizer cannot be notified that you want to change your answer:`,\n        };\n    }\n    if (originalInviteActions.type === DECLINE_INVITATION) {\n        return {\n            title: c('Title').t`Organizer cannot be notified`,\n            warningText: c('Info').t`The organizer cannot be notified that you decline the invitation:`,\n            alertText: c('Info').t`Would you like to delete the event anyway?`,\n            submit: (\n                <Button className=\"mlauto\" onClick={onSubmit} color=\"danger\" type=\"submit\">{c('Action')\n                    .t`Delete`}</Button>\n            ),\n        };\n    }\n    return {\n        title: c('Title').t`Participants cannot be notified`,\n        warningText:\n            newInviteActions.type === NONE\n                ? c('Info').t`None of the participants can be notified about your changes:`\n                : c('Info').t`The following participants cannot be notified about your changes:`,\n        alertText: c('Info').t`Would you like to continue anyway?`,\n        close: <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,\n        submit: <Button color=\"norm\" onClick={onSubmit}>{c('Action').t`Continue`}</Button>,\n    };\n};\n\ninterface Props {\n    sendPreferencesMap: SimpleMap<SendPreferences>;\n    inviteActions: InviteActions;\n    vevent?: VcalVeventComponent;\n    cancelVevent?: VcalVeventComponent;\n    onConfirm: (data: CleanSendIcsActionData) => void;\n    onClose: () => void;\n    isOpen: boolean;\n}\nconst SendWithErrorsConfirmationModal = ({\n    sendPreferencesMap,\n    inviteActions,\n    vevent,\n    cancelVevent,\n    onConfirm,\n    onClose,\n    isOpen,\n}: Props) => {\n    const errorMap = Object.entries(sendPreferencesMap).reduce<SimpleMap<string>>((acc, [email, sendPrefs]) => {\n        const error = sendPrefs?.error;\n        if (error) {\n            acc[email] = reformatApiErrorMessage(error.message);\n        }\n        return acc;\n    }, {});\n    const cleanSendData = getCleanSendData({\n        emailsWithError: Object.keys(errorMap),\n        sendPreferencesMap,\n        inviteActions,\n        vevent,\n        cancelVevent,\n    });\n    const handleConfirm = () => {\n        onConfirm(cleanSendData);\n        onClose();\n    };\n\n    const renderEmailRow = (email: string) => {\n        if (!cleanSendData.emailsWithError.includes(email)) {\n            return null;\n        }\n        const error = errorMap[email];\n        return (\n            <li key={email}>\n                <strong className=\"text-break\">\n                    {\n                        // translator: the colon character needs to be translated as well because of grammar differences between languages. Example: mail@cdn.com: error (english) and mail@ndd.fr : erreur (french)\n                        `${email}${c('colon').t`: `}`\n                    }\n                </strong>\n                {error}\n            </li>\n        );\n    };\n\n    const { title, warningText, alertText, submit, close } = getModalContent(\n        cleanSendData.inviteActions,\n        inviteActions,\n        onClose,\n        handleConfirm\n    );\n\n    return (\n        <BasicModal\n            title={title}\n            footer={\n                (close || submit) && (\n                    <>\n                        {close}\n                        {submit}\n                    </>\n                )\n            }\n            onSubmit={handleConfirm}\n            size=\"large\"\n            fullscreenOnMobile\n            onClose={onClose}\n            isOpen={isOpen}\n        >\n            <div className=\"mb1\">{warningText}</div>\n            <ul>{Object.keys(errorMap).map(renderEmailRow)}</ul>\n            {alertText && <div>{alertText}</div>}\n        </BasicModal>\n    );\n};\n\nexport default SendWithErrorsConfirmationModal;\n","import { Button, AlertModal } from '@proton/components';\nimport { c } from 'ttag';\n\ninterface CloseConfirmationModalProps {\n    onClose: () => void;\n    onSubmit: () => void;\n    isOpen: boolean;\n}\n\nconst CloseConfirmationModal = ({ onClose, onSubmit, isOpen }: CloseConfirmationModalProps) => {\n    return (\n        <AlertModal\n            title={c('Info').t`Discard changes?`}\n            onClose={onClose}\n            onSubmit={onSubmit}\n            open={isOpen}\n            buttons={[\n                <Button color=\"norm\" type=\"submit\" onClick={onSubmit}>{c('Action').t`Discard`}</Button>,\n                <Button type=\"reset\" autoFocus onClick={onClose}>{c('Action').t`Cancel`}</Button>,\n            ]}\n        >\n            {c('Info').t`You will lose all unsaved changes.`}\n        </AlertModal>\n    );\n};\n\nexport default CloseConfirmationModal;\n","import { c } from 'ttag';\nimport { AlertModal, Button } from '@proton/components';\nimport { RECURRING_TYPES } from '@proton/shared/lib/calendar/constants';\nimport { INVITE_ACTION_TYPES, InviteActions, RecurringActionData } from '../../../interfaces/Invite';\n\nconst { DECLINE_INVITATION, DECLINE_DISABLED, CANCEL_INVITATION, CANCEL_DISABLED } = INVITE_ACTION_TYPES;\n\nconst getTexts = ({ type, sendCancellationNotice }: InviteActions) => {\n    if (type === DECLINE_INVITATION && sendCancellationNotice) {\n        return {\n            title: c('Title').t`Delete event`,\n            submit: c('Action').t`Delete`,\n            alertText: c('Info')\n                .t`The organizer of this event will be notified that you decline the invitation. Would you like to delete this event?`,\n        };\n    }\n    if (type === DECLINE_DISABLED && sendCancellationNotice) {\n        return {\n            title: c('Title').t`Delete event`,\n            submit: c('Action').t`Delete`,\n            alertText: c('Info')\n                .t`The organizer of this event will not be notified that you decline the invitation as you can't send emails from the invited address. Would you like to delete this event anyway?`,\n        };\n    }\n    if (type === CANCEL_INVITATION) {\n        return {\n            title: c('Title').t`Delete event`,\n            submit: c('Action').t`Delete`,\n            alertText: c('Info')\n                .t`A cancellation email will be sent to the event participants. Would you like to delete this event?`,\n        };\n    }\n    if (type === CANCEL_DISABLED) {\n        return {\n            title: c('Title').t`Delete event`,\n            submit: c('Action').t`Delete`,\n            alertText: c('Info')\n                .t`Your address is disabled. A cancellation email cannot be sent to the event participants. Would you like to delete this event anyway?`,\n        };\n    }\n    return {\n        title: c('Title').t`Delete event`,\n        submit: c('Action').t`Delete`,\n        alertText: c('Info').t`Would you like to delete this event?`,\n    };\n};\n\ninterface Props {\n    onClose: () => void;\n    onConfirm: (data: RecurringActionData) => void;\n    inviteActions: InviteActions;\n    isOpen: boolean;\n}\n\nconst DeleteConfirmModal = ({ inviteActions, onConfirm, onClose, isOpen }: Props) => {\n    const { title, submit, alertText } = getTexts(inviteActions);\n    const handleSubmit = async () => {\n        onConfirm({ type: RECURRING_TYPES.SINGLE, inviteActions });\n        onClose();\n    };\n    return (\n        <AlertModal\n            title={title}\n            buttons={[\n                <Button color=\"danger\" onClick={handleSubmit} type=\"submit\">\n                    {submit}\n                </Button>,\n                <Button type=\"reset\" onClick={onClose} autoFocus>{c('Action').t`Cancel`}</Button>,\n            ]}\n            onSubmit={handleSubmit}\n            open={isOpen}\n        >\n            {alertText}\n        </AlertModal>\n    );\n};\n\nexport default DeleteConfirmModal;\n","import { InputHTMLAttributes } from 'react';\nimport { classnames } from '../../helpers';\n\nexport interface Props extends InputHTMLAttributes<HTMLInputElement> {\n    id: string;\n    className?: string;\n    name: string;\n}\n\nconst Radio = ({ id, children, className = 'inline-flex', name, ...rest }: Props) => (\n    <label\n        htmlFor={id}\n        className={classnames([!className?.includes('increase-click-surface') && 'relative', className])}\n    >\n        <input id={id} type=\"radio\" className=\"radio\" name={name} {...rest} />\n        <span className=\"radio-fakeradio flex-item-noshrink\" />\n        {children}\n    </label>\n);\n\nexport default Radio;\n","import { c } from 'ttag';\nimport { Radio, Row } from '@proton/components';\nimport * as React from 'react';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\nimport { RECURRING_TYPES } from '@proton/shared/lib/calendar/constants';\n\ninterface Props {\n    types: RECURRING_TYPES[];\n    type: RECURRING_TYPES;\n    setType: React.Dispatch<React.SetStateAction<RECURRING_TYPES>>;\n    'data-test-id': string;\n}\n\nconst SelectRecurringType = ({ types, type, setType, 'data-test-id': dataTestId }: Props) => {\n    const radios = [\n        types.includes(RECURRING_TYPES.SINGLE) && {\n            label: c('Option').t`This event`,\n            value: RECURRING_TYPES.SINGLE,\n        },\n        types.includes(RECURRING_TYPES.FUTURE) && {\n            label: c('Option').t`This and future events`,\n            value: RECURRING_TYPES.FUTURE,\n        },\n        types.includes(RECURRING_TYPES.ALL) && {\n            label: c('Option').t`All events`,\n            value: RECURRING_TYPES.ALL,\n        },\n    ].filter(isTruthy);\n\n    return (\n        <>\n            {radios.map(({ label, value }, i) => {\n                const id = i.toString();\n                return (\n                    <Row key={label}>\n                        <Radio\n                            className=\"flex-nowrap\"\n                            data-test-id={dataTestId}\n                            id={`recurringTypeChoice${id}`}\n                            name=\"recurringType\"\n                            checked={value === type}\n                            onChange={() => setType(value)}\n                        >\n                            {label}\n                        </Radio>\n                    </Row>\n                );\n            })}\n        </>\n    );\n};\n\nexport default SelectRecurringType;\n","import { useState } from 'react';\nimport { Alert, AlertModal, Button } from '@proton/components';\nimport { c } from 'ttag';\nimport { RECURRING_TYPES } from '@proton/shared/lib/calendar/constants';\nimport { INVITE_ACTION_TYPES, InviteActions, RecurringActionData } from '../../../interfaces/Invite';\nimport SelectRecurringType from './SelectRecurringType';\n\nconst getTexts = (types: RECURRING_TYPES[], inviteActions: InviteActions) => {\n    const { type: inviteType, sendCancellationNotice } = inviteActions;\n\n    const defaultTexts = {\n        title: c('Title').t`Delete recurring event`,\n        confirm: c('Action').t`Delete`,\n        alertText: c('Info').t`Which event would you like to delete?`,\n    };\n\n    if (types.length !== 1) {\n        return defaultTexts;\n    }\n    if (types[0] === RECURRING_TYPES.SINGLE) {\n        if (inviteType === INVITE_ACTION_TYPES.DECLINE_INVITATION) {\n            if (sendCancellationNotice) {\n                return {\n                    ...defaultTexts,\n                    alertText: c('Info')\n                        .t`This event has been updated. The organizer will be notified that you decline the invitation. Would you like to delete this event?`,\n                };\n            }\n            return {\n                ...defaultTexts,\n                alertText: c('Info')\n                    .t`This event has been updated by the organizer. Would you like to delete this event?`,\n            };\n        }\n        if (inviteType === INVITE_ACTION_TYPES.DECLINE_DISABLED && sendCancellationNotice) {\n            return {\n                ...defaultTexts,\n                alertText: c('Info')\n                    .t`This event has been updated. The organizer will not be notified that you decline the invitation as you can't send emails from the invited address. Would you like to delete this event anyway?`,\n            };\n        }\n        return {\n            ...defaultTexts,\n            alertText: c('Info').t`Would you like to delete this event?`,\n        };\n    }\n    if (types[0] === RECURRING_TYPES.ALL) {\n        if (inviteType === INVITE_ACTION_TYPES.CANCEL_INVITATION) {\n            return {\n                ...defaultTexts,\n                alertText: c('Info')\n                    .t`A cancellation email will be sent to the event participants. Would you like to delete all events in this series?`,\n            };\n        }\n        if (inviteType === INVITE_ACTION_TYPES.CANCEL_DISABLED) {\n            return {\n                ...defaultTexts,\n                alertText: c('Info')\n                    .t`Your address is disabled. A cancellation email cannot be sent to the event participants. Would you like to delete all events in this series anyway?`,\n            };\n        }\n        if (inviteType === INVITE_ACTION_TYPES.DECLINE_INVITATION && sendCancellationNotice) {\n            return {\n                ...defaultTexts,\n                alertText: c('Info')\n                    .t`The organizer of this series of events will be notified that you decline the invitation. Would you like to delete all the events in this series?`,\n            };\n        }\n        if (inviteType === INVITE_ACTION_TYPES.DECLINE_DISABLED && sendCancellationNotice) {\n            return {\n                ...defaultTexts,\n                alertText: c('Info')\n                    .t`The organizer of this series of events will not be notified that you decline the invitation as you can't send emails from the invited address. Would you like to delete all the events in this series anyway?`,\n            };\n        }\n        return {\n            ...defaultTexts,\n            alertText: c('Info').t`Would you like to delete all the events in this series?`,\n        };\n    }\n    // should never fall here\n    return {\n        title: '',\n        confirm: '',\n        alertText: '',\n    };\n};\n\nconst getRecurringWarningText = (isInvitation: boolean, inviteActions: InviteActions) => {\n    if (!isInvitation) {\n        return '';\n    }\n    if (inviteActions.resetSingleEditsPartstat) {\n        return c('Info')\n            .t`Occurrences previously updated by the organizer will be kept, but some of your answers will be lost.`;\n    }\n    return c('Info').t`Occurrences previously updated by the organizer will be kept.`;\n};\n\ninterface Props {\n    types: RECURRING_TYPES[];\n    isInvitation: boolean;\n    hasNonCancelledSingleEdits: boolean;\n    inviteActions: InviteActions;\n    onConfirm: (data: RecurringActionData) => void;\n    onClose: () => void;\n    isOpen: boolean;\n}\nconst DeleteRecurringConfirmModal = ({\n    types,\n    hasNonCancelledSingleEdits,\n    isInvitation,\n    inviteActions,\n    onConfirm,\n    onClose,\n    isOpen,\n}: Props) => {\n    const [type, setType] = useState(types[0]);\n    const { deleteSingleEdits } = inviteActions;\n    const { title, confirm, alertText } = getTexts(types, inviteActions);\n    const showWarning = hasNonCancelledSingleEdits && type === RECURRING_TYPES.ALL && !deleteSingleEdits;\n    const warningText = showWarning ? getRecurringWarningText(isInvitation, inviteActions) : '';\n    const handleConfirm = async () => {\n        onConfirm({ type, inviteActions });\n        onClose();\n    };\n\n    return (\n        <AlertModal\n            title={title}\n            buttons={[\n                <Button color=\"danger\" onClick={handleConfirm}>\n                    {confirm}\n                </Button>,\n                <Button type=\"reset\" onClick={onClose} autoFocus>{c('Action').t`Cancel`}</Button>,\n            ]}\n            onSubmit={handleConfirm}\n            open={isOpen}\n        >\n            <div className=\"mb1\">{alertText}</div>\n            {warningText && (\n                <Alert className=\"mb1\" type=\"warning\">\n                    {warningText}\n                </Alert>\n            )}\n            {types.length > 1 ? (\n                <SelectRecurringType\n                    types={types}\n                    type={type}\n                    setType={setType}\n                    data-test-id=\"delete-recurring-popover:delete-option-radio\"\n                />\n            ) : null}\n        </AlertModal>\n    );\n};\n\nexport default DeleteRecurringConfirmModal;\n","import { useState } from 'react';\nimport { Alert, Button, BasicModal } from '@proton/components';\nimport { c } from 'ttag';\nimport { RECURRING_TYPES } from '@proton/shared/lib/calendar/constants';\nimport { INVITE_ACTION_TYPES, InviteActions } from '../../../interfaces/Invite';\nimport SelectRecurringType from './SelectRecurringType';\n\nconst getTexts = (types: RECURRING_TYPES[], inviteActions: InviteActions) => {\n    const { type: inviteType, addedAttendees, removedAttendees, hasRemovedAllAttendees } = inviteActions;\n    const hasAddedAttendees = !!addedAttendees?.length;\n    const hasRemovedAttendees = !!removedAttendees?.length;\n\n    const defaultTexts = {\n        title: c('Title').t`Update recurring event`,\n        confirm: c('Action').t`Update`,\n        alertText: c('Info').t`Which event would you like to update?`,\n    };\n\n    if (types.length !== 1) {\n        return defaultTexts;\n    }\n    if (types[0] === RECURRING_TYPES.SINGLE) {\n        if (inviteType === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {\n            return {\n                ...defaultTexts,\n                alertText: c('Info')\n                    .t`This event has been updated by the organizer. Would you like to change your answer only for this occurrence in this series?`,\n            };\n        }\n        return {\n            ...defaultTexts,\n            alertText: c('Info').t`Would you like to update this event?`,\n        };\n    }\n    if (types[0] === RECURRING_TYPES.ALL) {\n        if (inviteType === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {\n            return {\n                ...defaultTexts,\n                alertText: c('Info').t`Would you like to change your answer for all the events in this series?`,\n            };\n        }\n        if (inviteType === INVITE_ACTION_TYPES.SEND_INVITATION) {\n            if (hasAddedAttendees && hasRemovedAttendees) {\n                return {\n                    title: c('Title').t`Save changes`,\n                    confirm: c('Action').t`Save`,\n                    alertText: c('Info')\n                        .t`Added and removed participants will be notified about all the events in this series.`,\n                };\n            }\n            if (hasAddedAttendees) {\n                return {\n                    title: c('Title').t`Add participants`,\n                    confirm: c('Action').t`Add`,\n                    alertText: c('Success')\n                        .t`An invitation will be sent to added participants for all the events in this series.`,\n                };\n            }\n            if (hasRemovedAttendees) {\n                return {\n                    title: c('Title').t`Remove participants`,\n                    confirm: c('Action').t`Remove`,\n                    alertText: c('Success')\n                        .t`A cancellation email will be sent to removed participants for all the events in this series.`,\n                };\n            }\n            // should never fall here\n            throw new Error('Inconsistent invite actions');\n        }\n        if (inviteType === INVITE_ACTION_TYPES.SEND_UPDATE) {\n            if (hasAddedAttendees && hasRemovedAttendees) {\n                if (hasRemovedAllAttendees) {\n                    return {\n                        title: c('Title').t`Save changes`,\n                        confirm: c('Action').t`Save`,\n                        alertText: c('Info')\n                            .t`You will update all the events in this series. Added and removed participants will be notified.`,\n                    };\n                }\n                return {\n                    title: c('Title').t`Save changes`,\n                    confirm: c('Action').t`Save`,\n                    alertText: c('Info')\n                        .t`You will update all the events in this series. Existent, added and removed participants will be notified.`,\n                };\n            }\n            if (hasAddedAttendees) {\n                return {\n                    title: c('Title').t`Save changes`,\n                    confirm: c('Action').t`Save`,\n                    alertText: c('Info')\n                        .t`You will update all the events in this series. Existent and added participants will be notified.`,\n                };\n            }\n            if (hasRemovedAllAttendees) {\n                return {\n                    title: c('Title').t`Save changes`,\n                    confirm: c('Action').t`Save`,\n                    alertText: c('Info')\n                        .t`You will update all the events in this series. Removed participants will be notified.`,\n                };\n            }\n            if (hasRemovedAttendees) {\n                return {\n                    title: c('Title').t`Save changes`,\n                    confirm: c('Action').t`Save`,\n                    alertText: c('Info')\n                        .t`You will update all the events in this series. Existent and removed participants will be notified.`,\n                };\n            }\n            return {\n                ...defaultTexts,\n                alertText: c('Info')\n                    .t`You will update all the events in this series. An invitation will be sent to the event participants.`,\n            };\n        }\n        return {\n            ...defaultTexts,\n            alertText: c('Info').t`Would you like to update all events in this series?`,\n        };\n    }\n    // should never fall here\n    throw new Error('Unknown confirmation type');\n};\n\nconst getRecurringWarningText = (isInvitation: boolean, inviteActions: InviteActions) => {\n    if (!isInvitation) {\n        return c('Info').t`Previous modifications on this series will be lost.`;\n    }\n    if (inviteActions.resetSingleEditsPartstat) {\n        return c('Info').t`Some of your answers to occurrences previously updated by the organizer will be lost.`;\n    }\n    return '';\n};\n\nconst getRruleWarningText = () => {\n    return c('Info').t`Frequency modifications will be lost.`;\n};\n\ninterface Props {\n    types: RECURRING_TYPES[];\n    hasSingleModifications: boolean;\n    hasSingleModificationsAfter: boolean;\n    hasRruleModification: boolean;\n    hasCalendarModification: boolean;\n    isInvitation: boolean;\n    inviteActions: InviteActions;\n    onConfirm: ({ type, inviteActions }: { type: RECURRING_TYPES; inviteActions: InviteActions }) => void;\n    onClose: () => void;\n    isOpen: boolean;\n}\nconst EditRecurringConfirmModal = ({\n    types,\n    hasSingleModifications,\n    hasSingleModificationsAfter,\n    hasRruleModification,\n    hasCalendarModification,\n    isInvitation,\n    inviteActions,\n    onConfirm,\n    onClose,\n    isOpen,\n}: Props) => {\n    const [type, setType] = useState(types[0]);\n\n    const { title, confirm, alertText } = getTexts(types, inviteActions);\n    const hasPreviousModifications =\n        (type === RECURRING_TYPES.ALL && hasSingleModifications) ||\n        (type === RECURRING_TYPES.FUTURE && hasSingleModificationsAfter);\n    const recurringWarningText = hasPreviousModifications ? getRecurringWarningText(isInvitation, inviteActions) : '';\n\n    const showRruleWarning = !isInvitation && type === RECURRING_TYPES.SINGLE && hasRruleModification;\n    const rruleWarningText = showRruleWarning ? getRruleWarningText() : '';\n\n    if (isInvitation && hasCalendarModification && hasPreviousModifications) {\n        const alertText = c('Info')\n            .t`The organizer has updated some of the events in this series. Changing the calendar is not supported yet for this type of recurring events.`;\n        return (\n            <BasicModal\n                title={c('Info').t`Update recurring event`}\n                footer={<Button onClick={onClose}>{c('Action').t`Cancel`}</Button>}\n                onClose={onClose}\n                size=\"small\"\n                isOpen={isOpen}\n            >\n                {alertText}\n            </BasicModal>\n        );\n    }\n\n    const handleSubmit = () => {\n        onConfirm({ type, inviteActions });\n    };\n\n    return (\n        <BasicModal\n            title={title}\n            footer={\n                <>\n                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                    <Button color=\"norm\" onClick={handleSubmit}>\n                        {confirm}\n                    </Button>\n                </>\n            }\n            onSubmit={handleSubmit}\n            onClose={onClose}\n            isOpen={isOpen}\n        >\n            <div className=\"mb1\">{alertText}</div>\n            {types.length > 1 ? (\n                <SelectRecurringType\n                    types={types}\n                    type={type}\n                    setType={setType}\n                    data-test-id=\"update-recurring-popover:update-option-radio\"\n                />\n            ) : null}\n            {recurringWarningText ? (\n                <Alert className=\"mb1\" type=\"warning\">\n                    {recurringWarningText}\n                </Alert>\n            ) : null}\n            {rruleWarningText ? (\n                <Alert className=\"mb1\" type=\"warning\">\n                    {rruleWarningText}\n                </Alert>\n            ) : null}\n        </BasicModal>\n    );\n};\n\nexport default EditRecurringConfirmModal;\n","import { c } from 'ttag';\nimport { Button, BasicModal } from '@proton/components';\nimport { RECURRING_TYPES } from '@proton/shared/lib/calendar/constants';\nimport { INVITE_ACTION_TYPES, InviteActions, RecurringActionData } from '../../../interfaces/Invite';\n\nconst { SEND_INVITATION, SEND_UPDATE } = INVITE_ACTION_TYPES;\n\nconst getTexts = ({ type, addedAttendees, removedAttendees, hasRemovedAllAttendees }: InviteActions) => {\n    const hasAddedAttendees = !!addedAttendees?.length;\n    const hasRemovedAttendees = !!removedAttendees?.length;\n    if (type === SEND_INVITATION) {\n        if (hasAddedAttendees && hasRemovedAttendees) {\n            return {\n                title: c('Title').t`Save changes`,\n                submit: c('Action').t`Save`,\n                alertText: c('Info').t`Added and removed participants will be notified.`,\n            };\n        }\n        if (hasAddedAttendees) {\n            return {\n                title: c('Title').t`Add participants`,\n                submit: c('Action').t`Add`,\n                alertText: c('Info').t`An invitation will be sent to added participants.`,\n            };\n        }\n        if (hasRemovedAttendees) {\n            return {\n                title: c('Title').t`Remove participants`,\n                submit: c('Action').t`Remove`,\n                alertText: c('Info').t`A cancellation email will be sent to removed participants.`,\n            };\n        }\n        return {\n            title: c('Title').t`Send invitation`,\n            submit: c('Action').t`Send`,\n            alertText: c('Info').t`An invitation will be sent to added participants.`,\n        };\n    }\n    if (type === SEND_UPDATE) {\n        if (hasAddedAttendees && hasRemovedAttendees) {\n            if (hasRemovedAllAttendees) {\n                return {\n                    title: c('Title').t`Save changes`,\n                    submit: c('Action').t`Save`,\n                    alertText: c('Info').t`Added and removed participants will be notified.`,\n                };\n            }\n            return {\n                title: c('Title').t`Save changes`,\n                submit: c('Action').t`Save`,\n                alertText: c('Info').t`Existent, added and removed participants will be notified.`,\n            };\n        }\n        if (hasAddedAttendees) {\n            return {\n                title: c('Title').t`Save changes`,\n                submit: c('Action').t`Save`,\n                alertText: c('Info').t`Existent and added participants will be notified.`,\n            };\n        }\n        if (hasRemovedAllAttendees) {\n            return {\n                title: c('Title').t`Save changes`,\n                submit: c('Action').t`Save`,\n                alertText: c('Info').t`Removed participants will be notified.`,\n            };\n        }\n        if (hasRemovedAttendees) {\n            return {\n                title: c('Title').t`Save changes`,\n                submit: c('Action').t`Save`,\n                alertText: c('Info').t`Existent and removed participants will be notified.`,\n            };\n        }\n        return {\n            title: c('Title').t`Update event`,\n            submit: c('Action').t`Update`,\n            alertText: c('Info').t`An invitation will be sent to the event participants.`,\n        };\n    }\n    // should never fall here\n    return {\n        title: '',\n        action: '',\n        alertText: '',\n    };\n};\n\ninterface Props {\n    inviteActions: InviteActions;\n    onConfirm: ({ type, inviteActions }: RecurringActionData) => void;\n    onClose: () => void;\n    isOpen: boolean;\n}\n\nconst EditSingleConfirmModal = ({ inviteActions, onConfirm, onClose, isOpen }: Props) => {\n    const { title, submit, alertText } = getTexts(inviteActions);\n    const handleSubmit = () => {\n        onConfirm({ type: RECURRING_TYPES.SINGLE, inviteActions });\n        onClose();\n    };\n    return (\n        <BasicModal\n            title={title}\n            footer={\n                <>\n                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                    <Button color=\"norm\" onClick={handleSubmit}>\n                        {submit}\n                    </Button>\n                </>\n            }\n            size=\"small\"\n            onSubmit={handleSubmit}\n            isOpen={isOpen}\n            onClose={onClose}\n        >\n            {alertText}\n        </BasicModal>\n    );\n};\n\nexport default EditSingleConfirmModal;\n","import { getOccurrences } from '@proton/shared/lib/calendar/recurring';\nimport { c } from 'ttag';\n\nimport { RECURRING_TYPES } from '@proton/shared/lib/calendar/constants';\nimport { INVITE_ACTION_TYPES, InviteActions } from '../../../interfaces/Invite';\nimport { EventNewData, EventOldData } from '../../../interfaces/EventData';\n\nexport const getEventCreatedText = (inviteActions: InviteActions) => {\n    const { type } = inviteActions;\n    if (type === INVITE_ACTION_TYPES.SEND_INVITATION) {\n        return c('Success').t`Invitation sent and event created`;\n    }\n    return c('Success').t`Event created`;\n};\n\nexport const getEventUpdatedText = (inviteActions: InviteActions) => {\n    const { type, addedAttendees, removedAttendees } = inviteActions;\n    const hasAddedAttendees = !!addedAttendees?.length;\n    const hasRemovedAttendees = !!removedAttendees?.length;\n    if (type === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {\n        return c('Success').t`Participation status updated`;\n    }\n    if (type === INVITE_ACTION_TYPES.SEND_INVITATION) {\n        if (hasAddedAttendees && hasRemovedAttendees) {\n            return c('Success').t`Participants notified and changes saved`;\n        }\n        if (hasAddedAttendees) {\n            return c('Success').t`Invitation sent and participants added`;\n        }\n        if (hasRemovedAttendees) {\n            return c('Success').t`Cancellation sent and participants removed`;\n        }\n        return c('Success').t`Participants notified and event updated`;\n    }\n    if (type === INVITE_ACTION_TYPES.SEND_UPDATE) {\n        return c('Success').t`Participants notified and event updated`;\n    }\n    return c('Success').t`Event updated`;\n};\n\nexport const getEventDeletedText = ({ type, sendCancellationNotice }: InviteActions) => {\n    if (type === INVITE_ACTION_TYPES.CANCEL_INVITATION) {\n        return c('Success').t`Cancellation sent and event deleted`;\n    }\n    if (type === INVITE_ACTION_TYPES.DECLINE_INVITATION && sendCancellationNotice) {\n        return c('Success').t`Answer sent and event deleted`;\n    }\n    return c('Success').t`Event deleted`;\n};\n\nexport const getRecurringEventCreatedText = (inviteActions: InviteActions) => {\n    if (inviteActions.type === INVITE_ACTION_TYPES.SEND_INVITATION) {\n        return c('Success').t`Invitation sent and events created`;\n    }\n    return c('Success').t`Events created`;\n};\n\nexport const getRecurringEventUpdatedText = (saveType: RECURRING_TYPES, inviteActions: InviteActions) => {\n    const { type: inviteType, addedAttendees, removedAttendees } = inviteActions;\n    const hasAddedAttendees = !!addedAttendees?.length;\n    const hasRemovedAttendees = !!removedAttendees?.length;\n    if (saveType === RECURRING_TYPES.SINGLE) {\n        return getEventUpdatedText(inviteActions);\n    }\n    if (saveType === RECURRING_TYPES.FUTURE) {\n        return c('Success').t`Future events updated`;\n    }\n    if (inviteType === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {\n        return c('Success').t`Participation status updated for all events`;\n    }\n    if (inviteType === INVITE_ACTION_TYPES.SEND_INVITATION) {\n        if (hasAddedAttendees && hasRemovedAttendees) {\n            return c('Success').t`Participants notified and all events updated`;\n        }\n        if (hasAddedAttendees) {\n            return c('Success').t`Invitation sent and participants added to all events`;\n        }\n        if (hasRemovedAttendees) {\n            return c('Success').t`Cancellation sent and participants removed from all events`;\n        }\n        // should never fall here\n        return c('Success').t`Invitation sent and all events updated`;\n    }\n    if (inviteType === INVITE_ACTION_TYPES.SEND_UPDATE) {\n        return c('Success').t`Participants notified and all events updated`;\n    }\n    return c('Success').t`All events updated`;\n};\n\nexport const getRecurringEventDeletedText = (deleteType: RECURRING_TYPES, inviteActions: InviteActions) => {\n    const { type, sendCancellationNotice } = inviteActions;\n    if (deleteType === RECURRING_TYPES.SINGLE) {\n        return getEventDeletedText(inviteActions);\n    }\n    if (deleteType === RECURRING_TYPES.FUTURE) {\n        return c('Success').t`Future events deleted`;\n    }\n    if (type === INVITE_ACTION_TYPES.CANCEL_INVITATION) {\n        return c('Success').t`Cancellation sent and all events deleted`;\n    }\n    if (type === INVITE_ACTION_TYPES.DECLINE_INVITATION && sendCancellationNotice) {\n        return c('Success').t`Answer sent and all events deleted`;\n    }\n    return c('Success').t`All events deleted`;\n};\n\nexport const getSingleEventText = (\n    oldEventData: EventOldData | undefined,\n    newEventData: EventNewData,\n    inviteActions: InviteActions\n) => {\n    const isCreate = !oldEventData?.eventData;\n    const isRecurring = newEventData.veventComponent.rrule;\n\n    if (isCreate && isRecurring) {\n        const twoOccurrences = getOccurrences({\n            component: newEventData.veventComponent,\n            maxCount: 2,\n        });\n        if (twoOccurrences.length === 1) {\n            return getEventCreatedText(inviteActions);\n        }\n        return getRecurringEventCreatedText(inviteActions);\n    }\n    if (isCreate) {\n        return getEventCreatedText(inviteActions);\n    }\n    return getEventUpdatedText(inviteActions);\n};\n","import { CALENDAR_CARD_TYPE } from '@proton/shared/lib/calendar/constants';\nimport { parse } from '@proton/shared/lib/calendar/vcal';\nimport { unwrap } from '@proton/shared/lib/calendar/helper';\nimport { CalendarEvent } from '@proton/shared/lib/interfaces/calendar';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\n\nconst { CLEAR_TEXT, SIGNED } = CALENDAR_CARD_TYPE;\n\nconst parseMainEventData = ({ SharedEvents = [] }: CalendarEvent): VcalVeventComponent | undefined => {\n    try {\n        const unencryptedPart = SharedEvents.find(({ Type }) => [CLEAR_TEXT, SIGNED].includes(Type));\n        const component = parse(unwrap(unencryptedPart?.Data || '')) as VcalVeventComponent;\n        if (component.component !== 'vevent') {\n            return undefined;\n        }\n        return component;\n    } catch (e: any) {\n        return undefined;\n    }\n};\n\nexport default parseMainEventData;\n","import { Address } from '@proton/shared/lib/interfaces';\nimport { CalendarEvent, CalendarMember } from '@proton/shared/lib/interfaces/calendar';\nimport parseMainEventData from './parseMainEventData';\nimport { getRecurrenceIdDate } from './getEventHelper';\nimport { getComponentWithPersonalPart } from '../../../helpers/event';\nimport { DecryptedEventTupleResult } from '../eventStore/interface';\n\ninterface GetEditEventDataArguments {\n    eventData: CalendarEvent;\n    eventResult?: DecryptedEventTupleResult;\n    memberResult: [CalendarMember, Address];\n}\n\nconst getEditEventData = ({ eventData, eventResult, memberResult: [member, address] }: GetEditEventDataArguments) => {\n    const mainVeventComponent = parseMainEventData(eventData);\n    if (!mainVeventComponent) {\n        throw new Error('Unparseable event');\n    }\n\n    const uid = mainVeventComponent.uid.value;\n    if (!uid) {\n        throw new Error('Event without UID');\n    }\n\n    const recurrenceID = getRecurrenceIdDate(mainVeventComponent);\n\n    const veventComponentFull = eventResult\n        ? getComponentWithPersonalPart({\n              decryptedEventResult: eventResult,\n              memberID: member.ID,\n          })\n        : undefined;\n\n    return {\n        eventData,\n        calendarID: eventData.CalendarID,\n        memberID: member.ID,\n        addressID: address.ID,\n        mainVeventComponent,\n        veventComponent: veventComponentFull,\n        uid,\n        recurrenceID,\n    };\n};\n\nexport default getEditEventData;\n","import { getOccurrences } from '@proton/shared/lib/calendar/recurring';\nimport { addMilliseconds } from '@proton/shared/lib/date-fns-utc';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\n\nimport { getRecurrenceIdDate } from './getEventHelper';\n\nconst getSingleEditRecurringData = (originalEvent: VcalVeventComponent, occurrenceEvent: VcalVeventComponent) => {\n    // If it's a single edition, the recurrence ID exists on the occurrence\n    const recurrenceID = getRecurrenceIdDate(occurrenceEvent);\n    if (!recurrenceID) {\n        throw new Error('Can only get event recurrence data for events with recurrence IDs');\n    }\n    // Since maxStart is inclusive, add one millisecond to ensure it would get included\n    const maxStart = addMilliseconds(recurrenceID, 1);\n\n    const occurrencesUntilDate = getOccurrences({\n        component: originalEvent,\n        maxCount: 10000000,\n        maxStart,\n    });\n\n    const twoOccurrences = getOccurrences({\n        component: originalEvent,\n        maxCount: 2,\n    });\n\n    // If no occurrences was found, it assumes that the recurrence-id is invalid.\n    // In that case, it falls back to the first occurrence\n    // It does that instead of throwing to allow the user to delete it, the effect is that it'll delete the closest event from the chain\n    const occurrences = occurrencesUntilDate.length === 0 ? twoOccurrences : occurrencesUntilDate;\n    const isSingleOccurrence = twoOccurrences.length === 1;\n\n    return {\n        ...occurrences[occurrences.length - 1],\n        isSingleOccurrence,\n    };\n};\n\nexport default getSingleEditRecurringData;\n","import { useGetAddressKeys } from '@proton/components';\nimport { useGetCalendarKeys } from '@proton/components/hooks/useGetDecryptedPassphraseAndCalendarKeys';\nimport { syncMultipleEvents as syncMultipleEventsRoute } from '@proton/shared/lib/api/calendars';\nimport { DEFAULT_ATTENDEE_PERMISSIONS } from '@proton/shared/lib/calendar/constants';\nimport getCreationKeys from '@proton/shared/lib/calendar/integration/getCreationKeys';\nimport {\n    createCalendarEvent,\n    getHasSharedEventContent,\n    getHasSharedKeyPacket,\n} from '@proton/shared/lib/calendar/serialize';\nimport { SimpleMap } from '@proton/shared/lib/interfaces';\nimport { CalendarEvent } from '@proton/shared/lib/interfaces/calendar';\nimport {\n    CreateCalendarEventSyncData,\n    CreateLinkedCalendarEventsSyncData,\n    DeleteCalendarEventSyncData,\n    DELETION_REASON,\n    UpdateCalendarEventSyncData,\n} from '@proton/shared/lib/interfaces/calendar/Api';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\nimport { OpenPGPKey } from 'pmcrypto';\n\nexport enum SyncOperationTypes {\n    DELETE,\n    UPDATE,\n    CREATE,\n}\n\nexport interface DeleteEventActionOperation {\n    type: SyncOperationTypes.DELETE;\n    data: {\n        calendarEvent: CalendarEvent;\n        deletionReason: DELETION_REASON;\n    };\n}\nexport interface CreateEventActionOperation {\n    type: SyncOperationTypes.CREATE;\n    data: {\n        veventComponent: VcalVeventComponent;\n        addedAttendeesPublicKeysMap?: SimpleMap<OpenPGPKey>;\n    };\n}\nexport interface UpdateEventActionOperation {\n    type: SyncOperationTypes.UPDATE;\n    data: {\n        calendarEvent: CalendarEvent;\n        veventComponent: VcalVeventComponent;\n        removedAttendeesEmails?: string[];\n        addedAttendeesPublicKeysMap?: SimpleMap<OpenPGPKey>;\n    };\n}\n\nexport type SyncEventActionOperation =\n    | CreateEventActionOperation\n    | UpdateEventActionOperation\n    | DeleteEventActionOperation;\n\nexport interface SyncEventActionOperations {\n    calendarID: string;\n    addressID: string;\n    memberID: string;\n    operations: SyncEventActionOperation[];\n}\n\nexport interface SyncMultipleEventsArguments {\n    sync: SyncEventActionOperations;\n    getCalendarKeys: ReturnType<typeof useGetCalendarKeys>;\n    getAddressKeys: ReturnType<typeof useGetAddressKeys>;\n}\n\nexport const getIsDeleteSyncOperation = (\n    operation: SyncEventActionOperation\n): operation is DeleteEventActionOperation => operation.type === SyncOperationTypes.DELETE;\nexport const getIsUpdateSyncOperation = (\n    operation: SyncEventActionOperation\n): operation is UpdateEventActionOperation => operation.type === SyncOperationTypes.UPDATE;\nexport const getIsCreateSyncOperation = (\n    operation: SyncEventActionOperation\n): operation is CreateEventActionOperation => operation.type === SyncOperationTypes.CREATE;\n\nexport const getCreateSyncOperation = (data: {\n    veventComponent: VcalVeventComponent;\n    addedAttendeesPublicKeysMap?: SimpleMap<OpenPGPKey>;\n}): CreateEventActionOperation => ({\n    type: SyncOperationTypes.CREATE,\n    data,\n});\nexport const getUpdateSyncOperation = (data: {\n    veventComponent: VcalVeventComponent;\n    calendarEvent: CalendarEvent;\n    removedAttendeesEmails?: string[];\n    addedAttendeesPublicKeysMap?: SimpleMap<OpenPGPKey>;\n}): UpdateEventActionOperation => ({\n    type: SyncOperationTypes.UPDATE,\n    data,\n});\n\nexport const getDeleteSyncOperation = (\n    calendarEvent: CalendarEvent,\n    isSwitchCalendar = false\n): DeleteEventActionOperation => ({\n    type: SyncOperationTypes.DELETE,\n    data: {\n        calendarEvent,\n        deletionReason: isSwitchCalendar ? DELETION_REASON.CHANGE_CALENDAR : DELETION_REASON.NORMAL,\n    },\n});\n\nconst getRequiredKeys = ({\n    sync: { operations, calendarID, addressID },\n    getCalendarKeys,\n    getAddressKeys,\n}: SyncMultipleEventsArguments) => {\n    const allCalendarIDs = operations.reduce<Set<string>>((acc, operation) => {\n        // No key needed for delete.\n        if (getIsDeleteSyncOperation(operation)) {\n            return acc;\n        }\n        if (getIsUpdateSyncOperation(operation)) {\n            const oldCalendarID = operation.data.calendarEvent.CalendarID;\n            const isSwitchCalendar = oldCalendarID !== calendarID;\n            if (isSwitchCalendar && oldCalendarID) {\n                acc.add(oldCalendarID);\n            }\n        }\n        acc.add(calendarID);\n        return acc;\n    }, new Set([calendarID]));\n\n    const getKeysMap = async <T>(set: Set<string>, cb: (id: string) => Promise<T[]>) => {\n        const ids = [...set];\n\n        const result = await Promise.all(ids.map(cb));\n\n        return ids.reduce<{ [id: string]: T[] }>((acc, id, i) => {\n            acc[id] = result[i];\n            return acc;\n        }, {});\n    };\n\n    return Promise.all([getKeysMap(allCalendarIDs, getCalendarKeys), getKeysMap(new Set([addressID]), getAddressKeys)]);\n};\n\nconst getSyncMultipleEventsPayload = async ({ getAddressKeys, getCalendarKeys, sync }: SyncMultipleEventsArguments) => {\n    const [calendarKeysMap, addressKeysMap] = await getRequiredKeys({ sync, getCalendarKeys, getAddressKeys });\n\n    const { operations, calendarID, memberID, addressID } = sync;\n\n    const payloadPromise = operations.map(\n        async (\n            operation\n        ): Promise<\n            | DeleteCalendarEventSyncData\n            | CreateCalendarEventSyncData\n            | UpdateCalendarEventSyncData\n            | CreateLinkedCalendarEventsSyncData\n        > => {\n            if (getIsDeleteSyncOperation(operation)) {\n                return { ID: operation.data.calendarEvent.ID, DeletionReason: operation.data.deletionReason };\n            }\n\n            const { veventComponent } = operation.data;\n\n            const newCalendarKeys = calendarKeysMap[calendarID];\n            const newAddressKeys = addressKeysMap[addressID];\n\n            const permissionData = {\n                Permissions: DEFAULT_ATTENDEE_PERMISSIONS,\n            };\n\n            if (getIsCreateSyncOperation(operation)) {\n                const { addedAttendeesPublicKeysMap } = operation.data;\n\n                const data = await createCalendarEvent({\n                    eventComponent: veventComponent,\n                    isCreateEvent: true,\n                    isSwitchCalendar: false,\n                    addedAttendeesPublicKeysMap,\n                    ...(await getCreationKeys({ newAddressKeys, newCalendarKeys })),\n                });\n\n                const dataComplete = {\n                    ...permissionData,\n                    ...data,\n                };\n\n                if (!getHasSharedKeyPacket(dataComplete) || !getHasSharedEventContent(dataComplete)) {\n                    throw new Error('Missing shared data');\n                }\n\n                return {\n                    Overwrite: 0,\n                    Event: dataComplete,\n                };\n            }\n\n            if (getIsUpdateSyncOperation(operation)) {\n                const { calendarEvent, removedAttendeesEmails, addedAttendeesPublicKeysMap } = operation.data;\n                const {\n                    CalendarID: oldCalendarID,\n                    AddressID: oldAddressID,\n                    SharedEventID: oldSharedEventID,\n                } = calendarEvent;\n\n                const isSwitchCalendar = oldCalendarID !== calendarID;\n\n                const oldAddressKeys = oldAddressID ? await getAddressKeys(oldAddressID) : undefined;\n                const oldCalendarKeys = isSwitchCalendar && oldCalendarID ? calendarKeysMap[oldCalendarID] : undefined;\n\n                const data = await createCalendarEvent({\n                    eventComponent: veventComponent,\n                    removedAttendeesEmails,\n                    addedAttendeesPublicKeysMap,\n                    isCreateEvent: false,\n                    isSwitchCalendar,\n                    isInvitation: !calendarEvent.IsOrganizer,\n                    ...(await getCreationKeys({\n                        calendarEvent,\n                        newAddressKeys,\n                        oldAddressKeys,\n                        newCalendarKeys,\n                        oldCalendarKeys,\n                    })),\n                });\n                const isOrganizerData = { IsOrganizer: operation.data.calendarEvent.IsOrganizer };\n\n                const dataComplete = {\n                    ...permissionData,\n                    ...isOrganizerData,\n                    ...data,\n                };\n\n                if (isSwitchCalendar) {\n                    if (!getHasSharedKeyPacket(dataComplete)) {\n                        throw new Error('Missing shared key packet');\n                    }\n                    return {\n                        Event: {\n                            ...dataComplete,\n                            SourceCalendarID: oldCalendarID,\n                            UID: veventComponent.uid.value,\n                            SharedEventID: oldSharedEventID,\n                        },\n                    };\n                }\n\n                if (!getHasSharedEventContent(dataComplete)) {\n                    throw new Error('Missing shared event content');\n                }\n\n                return {\n                    ID: calendarEvent.ID,\n                    Event: dataComplete,\n                };\n            }\n\n            throw new Error('Unknown operation');\n        }\n    );\n\n    return syncMultipleEventsRoute(calendarID, {\n        MemberID: memberID,\n        Events: await Promise.all(payloadPromise),\n    });\n};\n\nexport default getSyncMultipleEventsPayload;\n","import { CalendarEvent, VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar';\nimport { InviteActions, ReencryptInviteActionData } from '../../../interfaces/Invite';\n\nexport const getUpdatePersonalPartOperation = ({\n    eventComponent,\n    event,\n    memberID,\n    addressID,\n}: {\n    eventComponent: VcalVeventComponent;\n    event: CalendarEvent;\n    memberID: string;\n    addressID: string;\n}) => {\n    return {\n        data: {\n            memberID,\n            addressID,\n            calendarID: event.CalendarID,\n            eventID: event.ID,\n            eventComponent,\n        },\n    };\n};\n\nexport const getUpdatePersonalPartActions = async ({\n    eventComponent,\n    event,\n    memberID,\n    addressID,\n    reencryptionCalendarID,\n    inviteActions,\n    reencryptSharedEvent,\n}: {\n    eventComponent: VcalVeventComponent;\n    event: CalendarEvent;\n    memberID: string;\n    addressID: string;\n    reencryptionCalendarID?: string;\n    inviteActions: InviteActions;\n    reencryptSharedEvent: (data: ReencryptInviteActionData) => Promise<void>;\n}) => {\n    // Re-encrypt shared event first if needed\n    if (reencryptionCalendarID) {\n        await reencryptSharedEvent({ calendarEvent: event, calendarID: reencryptionCalendarID });\n    }\n    const updatePersonalPartAction = getUpdatePersonalPartOperation({\n        eventComponent,\n        event,\n        memberID,\n        addressID,\n    });\n    return {\n        multiSyncActions: [],\n        updatePersonalPartActions: [updatePersonalPartAction],\n        inviteActions,\n    };\n};\n","import { getUnixTime } from 'date-fns';\nimport { toIcsPartstat } from '@proton/shared/lib/calendar/attendees';\nimport { ICAL_ATTENDEE_STATUS } from '@proton/shared/lib/calendar/constants';\nimport { getAttendeeToken, getHasAttendees } from '@proton/shared/lib/calendar/vcalHelper';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\nimport { CalendarEvent, VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar';\nimport { serverTime } from 'pmcrypto';\nimport {\n    InviteActions,\n    ReencryptInviteActionData,\n    SendIcsActionData,\n    UpdatePartstatOperation,\n    UpdatePersonalPartOperation,\n} from '../../../interfaces/Invite';\nimport { SyncEventActionOperations } from '../getSyncMultipleEventsPayload';\nimport { getUpdatePersonalPartOperation } from './getUpdatePersonalPartActions';\n\nconst { ACCEPTED, TENTATIVE } = ICAL_ATTENDEE_STATUS;\n\nexport const getUpdatePartstatOperation = ({\n    eventComponent,\n    event,\n    inviteActions,\n    memberID,\n    timestamp,\n    silence,\n}: {\n    eventComponent: VcalVeventComponent;\n    event: CalendarEvent;\n    inviteActions: InviteActions;\n    memberID: string;\n    timestamp: number;\n    silence: boolean;\n}) => {\n    const { partstat, selfAttendeeIndex } = inviteActions;\n    if (selfAttendeeIndex === undefined || !partstat || !getHasAttendees(eventComponent)) {\n        return;\n    }\n    const token = eventComponent.attendee[selfAttendeeIndex]?.parameters?.['x-pm-token'];\n    const attendeeID = event.Attendees.find(({ Token }) => Token === token)?.ID;\n    if (!attendeeID) {\n        return;\n    }\n    return {\n        data: {\n            memberID,\n            calendarID: event.CalendarID,\n            eventID: event.ID,\n            attendeeID,\n            partstat,\n            updateTime: getUnixTime(timestamp),\n        },\n        silence,\n    };\n};\n\nconst getAutoUpdatePersonalPartOperation = ({\n    eventComponent,\n    event,\n    inviteActions,\n    memberID,\n    addressID,\n    partstat,\n}: {\n    eventComponent: VcalVeventComponent;\n    event: CalendarEvent;\n    inviteActions: InviteActions;\n    memberID: string;\n    addressID: string;\n    partstat: ICAL_ATTENDEE_STATUS;\n}) => {\n    const { selfAddress, selfAttendeeIndex } = inviteActions;\n    if (selfAttendeeIndex === undefined || !selfAddress || !getHasAttendees(eventComponent)) {\n        return;\n    }\n    const token = getAttendeeToken(eventComponent.attendee[selfAttendeeIndex]);\n    const oldAttendee = event.Attendees.find(({ Token }) => Token === token);\n    if (!oldAttendee) {\n        return;\n    }\n    const oldPartstat = toIcsPartstat(oldAttendee.Status);\n    if (\n        oldPartstat === partstat ||\n        (partstat === ACCEPTED && oldPartstat === TENTATIVE) ||\n        (partstat === TENTATIVE && oldPartstat === ACCEPTED)\n    ) {\n        // no need to update the notifications in such cases\n        return;\n    }\n    return getUpdatePersonalPartOperation({\n        eventComponent,\n        event,\n        memberID,\n        addressID,\n    });\n};\n\ninterface ChangePartstaActionsArguments {\n    inviteActions: InviteActions;\n    eventComponent: VcalVeventComponent;\n    event: CalendarEvent;\n    memberID: string;\n    addressID: string;\n    reencryptionCalendarID?: string;\n    sendIcs: (\n        data: SendIcsActionData\n    ) => Promise<{ veventComponent?: VcalVeventComponent; inviteActions: InviteActions; timestamp: number }>;\n    reencryptSharedEvent: (data: ReencryptInviteActionData) => Promise<void>;\n}\nconst getChangePartstatActions = async ({\n    inviteActions,\n    eventComponent,\n    event,\n    memberID,\n    addressID,\n    reencryptionCalendarID,\n    sendIcs,\n    reencryptSharedEvent,\n}: ChangePartstaActionsArguments): Promise<{\n    inviteActions: InviteActions;\n    multiSyncActions: SyncEventActionOperations[];\n    updatePartstatActions: UpdatePartstatOperation[];\n    updatePersonalPartActions: UpdatePersonalPartOperation[];\n    sendActions?: SendIcsActionData[];\n}> => {\n    const { partstat, isProtonProtonInvite } = inviteActions;\n    // Re-encrypt shared event first if needed\n    if (reencryptionCalendarID) {\n        await reencryptSharedEvent({ calendarEvent: event, calendarID: reencryptionCalendarID });\n    }\n\n    if (!partstat) {\n        throw new Error('Cannot update participation status without new answer');\n    }\n    // For Proton to Proton invites, we send the email after changing the answer\n    const timestamp = isProtonProtonInvite\n        ? +serverTime()\n        : (await sendIcs({ inviteActions, vevent: eventComponent })).timestamp;\n    const partstatOperation = getUpdatePartstatOperation({\n        eventComponent,\n        event,\n        inviteActions,\n        memberID,\n        timestamp,\n        silence: false,\n    });\n    if (!partstatOperation) {\n        throw new Error('Failed to generate change partstat operation');\n    }\n    const personalPartOperation = getAutoUpdatePersonalPartOperation({\n        eventComponent,\n        event,\n        inviteActions,\n        memberID,\n        addressID,\n        partstat,\n    });\n\n    return {\n        inviteActions,\n        multiSyncActions: [],\n        updatePartstatActions: [partstatOperation],\n        updatePersonalPartActions: [personalPartOperation].filter(isTruthy),\n        sendActions: isProtonProtonInvite ? [{ inviteActions, vevent: eventComponent }] : undefined,\n    };\n};\n\nexport default getChangePartstatActions;\n","import { getUntilProperty, propertyToUTCDate } from '@proton/shared/lib/calendar/vcalConverter';\nimport { getIsAllDay, getPropertyTzid } from '@proton/shared/lib/calendar/vcalHelper';\nimport { toUTCDate } from '@proton/shared/lib/date/timezone';\nimport { VcalRruleProperty, VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\n\nexport const getSafeRruleCount = (rrule: VcalRruleProperty, newCount: number) => {\n    if (newCount < 1) {\n        return;\n    }\n\n    return {\n        ...rrule,\n        value: {\n            ...rrule.value,\n            count: newCount,\n        },\n    };\n};\n\nexport const getSafeRruleUntil = (rrule: VcalRruleProperty, component: VcalVeventComponent) => {\n    const { dtstart } = component;\n\n    if (!rrule.value.until) {\n        throw new Error('Until required');\n    }\n\n    const originalUntilDateTime = toUTCDate(rrule.value.until);\n    const newStartTime = propertyToUTCDate(dtstart);\n\n    // If the event was moved after the until date, fixup the until\n    if (newStartTime > originalUntilDateTime) {\n        const until = getUntilProperty(dtstart.value, getIsAllDay(component), getPropertyTzid(dtstart));\n        return {\n            ...rrule,\n            value: {\n                ...rrule.value,\n                until,\n            },\n        };\n    }\n\n    return rrule;\n};\n","import { getIsPropertyAllDay, getPropertyTzid } from '@proton/shared/lib/calendar/vcalHelper';\nimport { fromUTCDate } from '@proton/shared/lib/date/timezone';\nimport { addDays } from '@proton/shared/lib/date-fns-utc';\nimport { omit } from '@proton/shared/lib/helpers/object';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\nimport { getUntilProperty } from '@proton/shared/lib/calendar/vcalConverter';\n\nimport { getSafeRruleCount } from './helper';\n\nconst deleteFutureRecurrence = (\n    component: VcalVeventComponent,\n    localStartToExclude: Date,\n    occurrenceNumber: number\n): VcalVeventComponent => {\n    const { dtstart, rrule } = component;\n\n    if (!rrule) {\n        throw new Error('Trying to delete future recurrence of a non-recurring event');\n    }\n\n    if (rrule.value.count) {\n        const newCount = occurrenceNumber - 1;\n        const safeRrule = getSafeRruleCount(rrule, newCount);\n        if (!safeRrule) {\n            return omit(component, ['rrule']);\n        }\n        return { ...component, rrule: safeRrule };\n    }\n\n    // Subtract one day from the local start, and get until property which in the end yields the previous day at 23:59:59\n    const until = getUntilProperty(\n        fromUTCDate(addDays(localStartToExclude, -1)),\n        getIsPropertyAllDay(dtstart),\n        getPropertyTzid(dtstart)\n    );\n\n    return {\n        ...component,\n        rrule: {\n            ...rrule,\n            value: {\n                ...rrule.value,\n                until,\n            },\n        },\n    };\n};\n\nexport default deleteFutureRecurrence;\n","import { addDays } from 'date-fns';\nimport { getDtendProperty } from '@proton/shared/lib/calendar/vcalConverter';\nimport { CalendarEvent } from '@proton/shared/lib/interfaces/calendar';\nimport { getOccurrences } from '@proton/shared/lib/calendar/recurring';\nimport { fromUTCDate, toUTCDate } from '@proton/shared/lib/date/timezone';\nimport { VcalDateOrDateTimeProperty, VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\nimport { getIsAllDay, getPropertyTzid, getRecurrenceId } from '@proton/shared/lib/calendar/vcalHelper';\nimport { toExdate } from '@proton/shared/lib/calendar/exdate';\n\nimport parseMainEventData from '../event/parseMainEventData';\nimport deleteFutureRecurrence from '../recurrence/deleteFutureRecurrence';\nimport { CalendarEventRecurring } from '../../../interfaces/CalendarEvents';\n\nexport const getOriginalEvent = (recurrences: CalendarEvent[]) => {\n    return recurrences.find((Event) => {\n        const component = parseMainEventData(Event);\n        if (!component) {\n            return false;\n        }\n        return !getRecurrenceId(component);\n    });\n};\n\nexport const getCurrentEvent = (originalComponent: VcalVeventComponent, recurrence: CalendarEventRecurring) => {\n    const isAllDay = getIsAllDay(originalComponent);\n    const { localStart, localEnd } = recurrence;\n    const correctedLocalEnd = isAllDay ? addDays(localEnd, 1) : localEnd;\n    const recurrenceDtstart = toExdate(fromUTCDate(localStart), isAllDay, getPropertyTzid(originalComponent.dtstart));\n    const recurrenceDtend = toExdate(\n        fromUTCDate(correctedLocalEnd),\n        isAllDay,\n        getPropertyTzid(getDtendProperty(originalComponent))\n    );\n\n    return {\n        ...originalComponent,\n        dtstart: recurrenceDtstart,\n        dtend: recurrenceDtend,\n    };\n};\n\nexport const getRecurrenceEvents = (recurrences: CalendarEvent[], originalEvent: CalendarEvent) => {\n    return recurrences.filter((Event) => Event.ID !== originalEvent.ID);\n};\n\nexport const getExdatesAfter = (exdates: VcalDateOrDateTimeProperty[], date: Date) => {\n    if (!Array.isArray(exdates)) {\n        return [];\n    }\n    return exdates.filter((exdate) => {\n        const recurrenceId = toUTCDate(exdate.value);\n        return recurrenceId >= date;\n    });\n};\n\nexport const getRecurrenceEventsAfter = (recurrences: CalendarEvent[], date: Date) => {\n    return recurrences.filter((Event) => {\n        const component = parseMainEventData(Event);\n        if (!component) {\n            return false;\n        }\n        const rawRecurrenceId = getRecurrenceId(component);\n        if (!rawRecurrenceId || !rawRecurrenceId.value) {\n            return false;\n        }\n        const recurrenceId = toUTCDate(rawRecurrenceId.value);\n        return recurrenceId >= date;\n    });\n};\n\nexport const getHasFutureOption = (veventComponent: VcalVeventComponent, recurrence: CalendarEventRecurring) => {\n    if (recurrence.occurrenceNumber === 1) {\n        return false;\n    }\n\n    // Dry-run delete this and future recurrences\n    const veventFutureDeleted = deleteFutureRecurrence(\n        veventComponent,\n        recurrence.localStart,\n        recurrence.occurrenceNumber\n    );\n\n    // If we would end up with at least 1 occurrence, the delete this and future option is allowed\n    return getOccurrences({ component: veventFutureDeleted, maxCount: 2 }).length >= 1;\n};\n","import { getIsPropertyAllDay, getPropertyTzid } from '@proton/shared/lib/calendar/vcalHelper';\nimport { fromUTCDate, toUTCDate } from '@proton/shared/lib/date/timezone';\nimport { uniqueBy } from '@proton/shared/lib/helpers/array';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\nimport { toExdate } from '@proton/shared/lib/calendar/exdate';\n\nconst deleteSingleRecurrence = (component: VcalVeventComponent, localStartToExclude: Date) => {\n    const { dtstart, exdate: oldExdate = [] } = component;\n\n    const singleExdate = toExdate(\n        fromUTCDate(localStartToExclude),\n        getIsPropertyAllDay(dtstart),\n        getPropertyTzid(dtstart)\n    );\n\n    const newExdates = uniqueBy([...oldExdate, singleExdate], (property) => {\n        return +toUTCDate(property.value);\n    }).sort((a, b) => {\n        return +toUTCDate(a.value) - +toUTCDate(b.value);\n    });\n\n    return {\n        ...component,\n        exdate: newExdates,\n    } as VcalVeventComponent;\n};\n\nexport default deleteSingleRecurrence;\n","import {\n    ICAL_ATTENDEE_STATUS,\n    DELETE_CONFIRMATION_TYPES,\n    RECURRING_TYPES,\n} from '@proton/shared/lib/calendar/constants';\nimport { getHasNonCancelledSingleEdits, getMustResetPartstat } from '@proton/shared/lib/calendar/integration/invite';\nimport { CalendarEvent } from '@proton/shared/lib/interfaces/calendar';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\n\nimport { getHasFutureOption, getRecurrenceEvents } from './recurringHelper';\nimport { InviteActions } from '../../../interfaces/Invite';\n\nimport { OnDeleteConfirmationCb } from '../interface';\nimport { EventOldData } from '../../../interfaces/EventData';\nimport { CalendarEventRecurring } from '../../../interfaces/CalendarEvents';\n\ninterface Arguments {\n    originalEditEventData: EventOldData;\n    recurrences: CalendarEvent[];\n    recurrence: CalendarEventRecurring;\n    inviteActions: InviteActions;\n    veventComponent?: VcalVeventComponent;\n    canOnlyDeleteAll: boolean;\n    canOnlyDeleteThis: boolean;\n    isCalendarDisabled: boolean;\n    isInvitation: boolean;\n    onDeleteConfirmation: OnDeleteConfirmationCb;\n    selfAttendeeToken?: string;\n}\nconst getRecurringDeleteType = ({\n    originalEditEventData,\n    recurrences,\n    recurrence,\n    canOnlyDeleteAll,\n    canOnlyDeleteThis,\n    isCalendarDisabled,\n    isInvitation,\n    onDeleteConfirmation,\n    inviteActions,\n    selfAttendeeToken,\n}: Arguments) => {\n    let deleteTypes;\n    if (canOnlyDeleteAll || !originalEditEventData.veventComponent) {\n        deleteTypes = [RECURRING_TYPES.ALL];\n    } else if (canOnlyDeleteThis) {\n        deleteTypes = [RECURRING_TYPES.SINGLE];\n    } else if (getHasFutureOption(originalEditEventData.veventComponent, recurrence)) {\n        deleteTypes = [RECURRING_TYPES.SINGLE, RECURRING_TYPES.FUTURE, RECURRING_TYPES.ALL];\n    } else {\n        deleteTypes = [RECURRING_TYPES.SINGLE, RECURRING_TYPES.ALL];\n    }\n    const singleEditRecurrences = getRecurrenceEvents(recurrences, originalEditEventData.eventData);\n    const singleEditRecurrencesWithoutSelf = singleEditRecurrences.filter((event) => {\n        return event.ID !== originalEditEventData.eventData.ID;\n    });\n    const mustResetPartstat = getMustResetPartstat(\n        singleEditRecurrencesWithoutSelf,\n        selfAttendeeToken,\n        ICAL_ATTENDEE_STATUS.DECLINED\n    );\n    const updatedInviteActions = {\n        ...inviteActions,\n        resetSingleEditsPartstat:\n            deleteTypes.length === 1 &&\n            deleteTypes[0] === RECURRING_TYPES.ALL &&\n            mustResetPartstat &&\n            !isCalendarDisabled,\n        deleteSingleEdits: isCalendarDisabled,\n    };\n    const hasNonCancelledSingleEdits = getHasNonCancelledSingleEdits(singleEditRecurrencesWithoutSelf);\n    return onDeleteConfirmation({\n        type: DELETE_CONFIRMATION_TYPES.RECURRING,\n        data: { types: deleteTypes, hasNonCancelledSingleEdits },\n        inviteActions: updatedInviteActions,\n        isInvitation,\n    });\n};\n\nexport default getRecurringDeleteType;\n","import { Address } from '../interfaces';\nimport { addPlusAlias, canonizeInternalEmail } from '../helpers/email';\n\n/**\n * Get address from email\n * Remove + alias and transform to lower case\n */\nexport const getByEmail = (addresses: Address[], email = '') => {\n    const value = canonizeInternalEmail(email);\n    return addresses.find(({ Email }) => canonizeInternalEmail(Email) === value);\n};\n\n/**\n * Detect if the email address is a valid plus alias and returns the address model appropriate\n */\nexport const getAddressFromPlusAlias = (addresses: Address[], email = ''): Address | undefined => {\n    const plusIndex = email.indexOf('+');\n    const atIndex = email.indexOf('@');\n\n    if (plusIndex === -1 || atIndex === -1) {\n        return;\n    }\n\n    // Remove the plus alias part to find a match with existing addresses\n    const address = getByEmail(addresses, email);\n    const { Status, Receive, Send } = address || {};\n\n    if (!Status || !Receive || !Send) {\n        // pm.me addresses on free accounts (Send = 0)\n        return;\n    }\n\n    const plusPart = email.substring(plusIndex + 1, atIndex);\n\n    // Returns an address where the Email is build to respect the existing capitalization and add the plus part\n    return { ...(address as Address), Email: addPlusAlias(address?.Email, plusPart) };\n};\n\nexport const getSupportedPlusAlias = ({\n    selfAttendeeEmail,\n    selfAddressEmail,\n}: {\n    selfAttendeeEmail: string;\n    selfAddressEmail: string;\n}) => {\n    if (!selfAttendeeEmail) {\n        return selfAddressEmail;\n    }\n\n    const plusIndex = selfAttendeeEmail.indexOf('+');\n    const atIndex = selfAttendeeEmail.indexOf('@');\n    const plusPart = selfAttendeeEmail.substring(plusIndex + 1, atIndex);\n\n    if (plusIndex === -1) {\n        return selfAddressEmail;\n    }\n\n    return addPlusAlias(selfAddressEmail, plusPart);\n};\n","import { convertZonedDateTimeToUTC, fromUTCDate, toUTCDate } from '../date/timezone';\nimport { VcalVeventComponent } from '../interfaces/calendar';\nimport { getOccurrences, getOccurrencesBetween, RecurringResult } from './recurring';\nimport { getIsRruleEqual } from './rruleEqual';\nimport { propertyToUTCDate } from './vcalConverter';\nimport { getIsAllDay, getPropertyTzid } from './vcalHelper';\n\nexport const getAreOccurrencesSubset = (\n    newOccurrences: (RecurringResult | Pick<RecurringResult, 'localStart'>)[],\n    oldVevent: VcalVeventComponent\n) => {\n    const cache = {};\n    for (const { localStart } of newOccurrences) {\n        const isAllDay = getIsAllDay(oldVevent);\n        const startTzid = getPropertyTzid(oldVevent.dtstart);\n        let utcStart = localStart;\n        if (!isAllDay && startTzid) {\n            utcStart = toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(localStart), startTzid));\n        }\n        const [oldOccurrence] = getOccurrencesBetween(oldVevent, +utcStart, +utcStart, cache);\n        if (!oldOccurrence) {\n            return false;\n        }\n    }\n    return true;\n};\n\n/**\n * Return true if the set of occurrences of the new rrule is contained (equality counts) in the old rrule.\n * Return false otherwise\n * We restrict to rrules that can be created by us\n */\nexport const getIsRruleSubset = (newVevent: VcalVeventComponent, oldVevent: VcalVeventComponent) => {\n    const [{ rrule: newRrule, dtstart: newDtstart }, { rrule: oldRrule }] = [newVevent, oldVevent];\n    const isRruleEqual = getIsRruleEqual(newRrule, oldRrule);\n    if (!newRrule || !oldRrule || isRruleEqual) {\n        return isRruleEqual;\n    }\n    const { count: oldCount, until: oldUntil } = oldRrule.value;\n    const { count: newCount, until: newUntil } = newRrule.value;\n    if (!newCount && !newUntil && (oldCount || oldUntil)) {\n        return false;\n    }\n    /**\n     *  Given the repeating nature of recurring rules, we're gonna play dirty here\n     *  and simply check if the at max 10 first occurrences of the new recurring rule are generated by the old one.\n     *  For the recurring rules we support this is more than enough, but it wouldn't be\n     *  in a more general (and pathological) scenario.\n     *  The alternative would be to write some code checking the frequency, interval,\n     *  byday, etc properties and going case by case. That code would be cumbersome and ugly\n     */\n    // either newUntil or newCount are not undefined, so we can check if all new occurrences are in the original set\n    // but for performance we use the same trick as above and check max 10\n    const maxCount = newCount ? Math.min(newCount, 10) : 10;\n    const newOccurrences = newUntil\n        ? getOccurrencesBetween(newVevent, +propertyToUTCDate(newDtstart), +toUTCDate(newUntil)).slice(0, 10)\n        : getOccurrences({ component: newVevent, maxCount });\n\n    return getAreOccurrencesSubset(newOccurrences, oldVevent);\n};\n","import { getHasUpdatedInviteData } from '@proton/shared/lib/calendar/integration/invite';\nimport { withDtstamp } from '@proton/shared/lib/calendar/veventHelper';\nimport { omit } from '@proton/shared/lib/helpers/object';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar';\n\n/**\n * DTSTAMP functions as sort of a LAST-MODIFIED timestamp, but only for invite-related modifications\n */\nexport const withUpdatedDtstamp = (newVevent: VcalVeventComponent, oldVevent?: VcalVeventComponent) => {\n    if (!getHasUpdatedInviteData({ newVevent, oldVevent })) {\n        return { ...newVevent };\n    }\n    return withDtstamp(omit(newVevent, ['dtstamp']));\n};\n","import { getIsRruleSubset } from '@proton/shared/lib/calendar/rruleSubset';\nimport { getHasModifiedDateTimes } from '@proton/shared/lib/calendar/vcalConverter';\nimport { getIsPropertyAllDay } from '@proton/shared/lib/calendar/vcalHelper';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\nimport { withUpdatedDtstamp } from './dtstamp';\n\nexport const withIncrementedSequence = (vevent: VcalVeventComponent) => {\n    const sequenceValue = vevent.sequence?.value;\n    if (sequenceValue === undefined) {\n        return { ...vevent, sequence: { value: 0 } };\n    }\n    return {\n        ...vevent,\n        sequence: { value: Math.max(0, sequenceValue) + 1 },\n    };\n};\n\nexport const withVeventSequence = (vevent: VcalVeventComponent, oldVevent: VcalVeventComponent) => {\n    if (oldVevent.sequence?.value === undefined) {\n        return { ...vevent, sequence: { value: 0 } };\n    }\n    const { dtstart } = vevent;\n    const { dtstart: oldDtstart, sequence: oldSequence } = oldVevent;\n    const { sequence: newSequence } = vevent;\n    const [isAllDay, oldIsAllDay] = [dtstart, oldDtstart].map(getIsPropertyAllDay);\n    const isAllDayPreserved = isAllDay === oldIsAllDay;\n    const areDateTimesPreserved = !getHasModifiedDateTimes(vevent, oldVevent);\n    const isRrulePreservedOrSubset =\n        isAllDayPreserved && areDateTimesPreserved ? getIsRruleSubset(vevent, oldVevent) : false;\n    const oldSequenceValue = Math.max(0, oldSequence.value);\n    if (isAllDayPreserved && areDateTimesPreserved && isRrulePreservedOrSubset) {\n        return newSequence ? { ...vevent } : { ...vevent, seq