n    return alarms.find(({ ID }) => {\n        return !set.has(ID);\n    });\n};\n\ninterface Props {\n    alarms: CalendarAlarm[];\n    tzid: string;\n    calendarsEventsCacheRef: MutableRefObject<CalendarsEventsCache>;\n}\nconst AlarmWatcher = ({ alarms = [], tzid, calendarsEventsCacheRef }: Props) => {\n    const api = useApi();\n    const hasSuspendedCounter = useHasSuspendedCounter({ refreshInterval: MINUTE, tolerance: MINUTE / 2 });\n    const getCalendarEventRaw = useGetCalendarEventRaw();\n    const cacheRef = useRef<Set<string>>();\n\n    useEffect(() => {\n        let timeoutHandle = 0;\n        let unmounted = false;\n\n        const run = () => {\n            if (unmounted) {\n                return;\n            }\n            if (!cacheRef.current) {\n                cacheRef.current = new Set();\n            }\n\n            const firstUnseenAlarm = getFirstUnseenAlarm(alarms, cacheRef.current);\n            if (!firstUnseenAlarm) {\n                return;\n            }\n\n            const { ID, Occurrence, Trigger, CalendarID, EventID } = firstUnseenAlarm;\n\n            const nextAlarmTime = fromUnixTime(Occurrence);\n            const now = Date.now();\n            const diff = differenceInMilliseconds(nextAlarmTime, now);\n            const delay = Math.max(diff, 0);\n\n            const getEvent = () => {\n                const cachedEvent = calendarsEventsCacheRef.current.getCachedEvent(CalendarID, EventID);\n                if (cachedEvent) {\n                    return Promise.resolve(cachedEvent);\n                }\n                return api<{ Event: CalendarEvent }>({ ...getEventRoute(CalendarID, EventID), silence: true }).then(\n                    ({ Event }) => Event\n                );\n            };\n\n            timeoutHandle = window.setTimeout(() => {\n                if (unmounted || !cacheRef.current) {\n                    return;\n                }\n                // Eagerly add the event to seen, ignore if it would fail\n                cacheRef.current.add(ID);\n\n                // Ignore the event if it's in the past after the cutoff\n                if (diff < MIN_CUTOFF) {\n                    window.setTimeout(run, 0);\n                    return;\n                }\n\n                getEvent()\n                    .then((Event) => getCalendarEventRaw(Event))\n                    .then((eventRaw) => {\n                        if (unmounted) {\n                            return;\n                        }\n                        const { veventComponent: component } = eventRaw;\n                        // compute event start time based on trigger, as we cannot rely on dtstart for recurring events\n                        const start = new Date(getNextEventTime({ Occurrence, Trigger, tzid }));\n                        const now = new Date();\n                        const formatOptions = { locale: dateLocale };\n                        const text = getAlarmMessage({ component, start, now, tzid, formatOptions });\n                        return displayNotification({ text, tag: ID });\n                    })\n                    .catch(noop);\n\n                window.setTimeout(run, 0);\n            }, delay);\n        };\n\n        run();\n\n        return () => {\n            unmounted = true;\n            if (timeoutHandle) {\n                window.clearTimeout(timeoutHandle);\n            }\n        };\n    }, [alarms, tzid, getCalendarEventRaw, hasSuspendedCounter]);\n\n    return null;\n};\n\nexport default AlarmWatcher;\n","import { MutableRefObject } from 'react';\nimport { Calendar } from '@proton/shared/lib/interfaces/calendar';\nimport AlarmWatcher from './AlarmWatcher';\nimport useCalendarsAlarms from './useCalendarsAlarms';\nimport { CalendarsAlarmsCache } from './CacheInterface';\nimport { CalendarsEventsCache } from '../calendar/eventStore/interface';\n\ninterface Props {\n    calendars: Calendar[];\n    tzid: string;\n    calendarsAlarmsCacheRef: MutableRefObject<CalendarsAlarmsCache>;\n    calendarsEventsCacheRef: MutableRefObject<CalendarsEventsCache>;\n}\n\nconst AlarmContainer = ({ calendars, tzid, calendarsAlarmsCacheRef, calendarsEventsCacheRef }: Props) => {\n    const alarms = useCalendarsAlarms(calendars, calendarsAlarmsCacheRef);\n    return <AlarmWatcher alarms={alarms} tzid={tzid} calendarsEventsCacheRef={calendarsEventsCacheRef} />;\n};\n\nexport default AlarmContainer;\n","import { MutableRefObject, useEffect } from 'react';\nimport { LoaderPage, useNotifications, useApi, useCache } from '@proton/components';\nimport { useHistory } from 'react-router-dom';\nimport { c } from 'ttag';\nimport { getUnixTime } from 'date-fns';\nimport { Address } from '@proton/shared/lib/interfaces';\nimport { VisualCalendar, CalendarEvent } from '@proton/shared/lib/interfaces/calendar';\nimport { getEvent, updateMember } from '@proton/shared/lib/api/calendars';\nimport { getMemberAndAddress } from '@proton/shared/lib/calendar/members';\nimport { getDateOrDateTimeProperty, propertyToUTCDate } from '@proton/shared/lib/calendar/vcalConverter';\nimport { loadModels } from '@proton/shared/lib/models/helper';\nimport { CalendarsModel } from '@proton/shared/lib/models';\nimport { MAXIMUM_DATE, MINIMUM_DATE } from '@proton/shared/lib/calendar/constants';\nimport { convertUTCDateTimeToZone, fromUTCDate, toUTCDate } from '@proton/shared/lib/date/timezone';\nimport { addMilliseconds, isSameDay } from '@proton/shared/lib/date-fns-utc';\nimport { getOccurrences } from '@proton/shared/lib/calendar/recurring';\nimport { VcalVeventComponent } from '@proton/shared/lib/interfaces/calendar/VcalModel';\nimport { getIsPropertyAllDay, getPropertyTzid } from '@proton/shared/lib/calendar/vcalHelper';\nimport getRecurrenceIdValueFromTimestamp from '@proton/shared/lib/calendar/getRecurrenceIdValueFromTimestamp';\nimport parseMainEventData from './event/parseMainEventData';\nimport { getRecurrenceIdDate } from './event/getEventHelper';\nimport { EventTargetAction } from './interface';\nimport { getCalendarEventStoreRecord } from './eventStore/cache/upsertCalendarEventStoreRecord';\nimport getAllEventsByUID from './getAllEventsByUID';\n\ninterface Props {\n    addresses: Address[];\n    calendars: VisualCalendar[];\n    tzid: string;\n    eventTargetActionRef: MutableRefObject<EventTargetAction | undefined>;\n}\nconst EventActionContainer = ({ tzid, addresses, calendars, eventTargetActionRef }: Props) => {\n    const { createNotification } = useNotifications();\n    const history = useHistory();\n    const api = useApi();\n    const cache = useCache();\n\n    useEffect(() => {\n        const run = async () => {\n            const params = new URLSearchParams(window.location.search);\n            const action = params.get('Action');\n\n            if (action === 'VIEW') {\n                const handleLinkError = () => {\n                    createNotification({\n                        type: 'error',\n                        text: c('Error').t`Invalid link to the event`,\n                    });\n                    history.replace('/');\n                };\n\n                const handleOtherError = () => {\n                    history.replace('/');\n                };\n\n                const handleGotoRange = (date: Date) => {\n                    history.replace(\n                        `/week/${[date.getUTCFullYear(), date.getUTCMonth() + 1, date.getUTCDate()].join('/')}`\n                    );\n                };\n\n                const handleGotoOccurrence = (\n                    eventData: CalendarEvent,\n                    eventComponent: VcalVeventComponent,\n                    occurrence: { localStart: Date; occurrenceNumber: number }\n                ) => {\n                    const { isAllDay, isAllPartDay } = getCalendarEventStoreRecord(eventComponent, eventData);\n\n                    const withOccurrenceDtstart = getDateOrDateTimeProperty(\n                        eventComponent.dtstart,\n                        occurrence.localStart\n                    );\n                    const utcDate = propertyToUTCDate(withOccurrenceDtstart);\n                    const startInTzid = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcDate), tzid));\n                    eventTargetActionRef.current = {\n                        id: `${eventData.ID}-${occurrence.occurrenceNumber}`,\n                        isAllDay,\n                        isAllPartDay,\n                        startInTzid,\n                    };\n                    return handleGotoRange(startInTzid);\n                };\n\n                const handleGotoEvent = (eventData: CalendarEvent, eventComponent: VcalVeventComponent) => {\n                    const { isAllDay, isAllPartDay } = getCalendarEventStoreRecord(eventComponent, eventData);\n\n                    const utcDate = propertyToUTCDate(eventComponent.dtstart);\n                    const startInTzid = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcDate), tzid));\n                    eventTargetActionRef.current = {\n                        id: eventData.ID,\n                        isAllDay,\n                        isAllPartDay,\n                        startInTzid,\n                    };\n                    return handleGotoRange(startInTzid);\n                };\n\n                const calendarID = params.get('CalendarID');\n                const eventID = params.get('EventID');\n                const recurrenceId = params.get('RecurrenceID');\n\n                if (!calendarID || !eventID) {\n                    return handleLinkError();\n                }\n                const calendar = calendars.find(({ ID }) => ID === calendarID);\n                if (!calendar) {\n                    return handleLinkError();\n                }\n                if (!calendar.Display) {\n                    const [{ ID: memberID }] = getMemberAndAddress(addresses, calendar.Members);\n                    await api({\n                        ...updateMember(calendarID, memberID, { Display: 1 }),\n                        silence: true,\n                    }).catch(() => {});\n                    await loadModels([CalendarsModel], { api, cache, useCache: false });\n                }\n                try {\n                    const result = await api<{ Event: CalendarEvent }>({\n                        ...getEvent(calendarID, eventID),\n                        silence: true,\n                    });\n                    const parsedEvent = parseMainEventData(result.Event);\n\n                    if (!parsedEvent) {\n                        throw new Error('Missing parsed event');\n                    }\n\n                    if (!parsedEvent.rrule) {\n                        return handleGotoEvent(result.Event, parsedEvent);\n                    }\n\n                    if (!recurrenceId) {\n                        const occurrences = getOccurrences({ component: parsedEvent, maxCount: 1 });\n                        if (!occurrences.length) {\n                            return handleLinkError();\n                        }\n                        const [firstOccurrence] = occurrences;\n                        return handleGotoOccurrence(result.Event, parsedEvent, firstOccurrence);\n                    }\n\n                    const parsedRecurrenceID = parseInt(recurrenceId || '', 10);\n\n                    if (\n                        !Number.isInteger(parsedRecurrenceID) ||\n                        parsedRecurrenceID < getUnixTime(MINIMUM_DATE) ||\n                        parsedRecurrenceID > getUnixTime(MAXIMUM_DATE)\n                    ) {\n                        return handleLinkError();\n                    }\n\n                    const eventsByUID = await getAllEventsByUID(api, calendarID, parsedEvent.uid.value);\n\n                    const { dtstart } = parsedEvent;\n                    const localRecurrenceID = toUTCDate(\n                        getRecurrenceIdValueFromTimestamp(\n                            parsedRecurrenceID,\n                            getIsPropertyAllDay(dtstart),\n                            getPropertyTzid(dtstart) || 'UTC'\n                        ).value\n                    );\n\n                    const isTargetOccurrenceEdited = eventsByUID.some((recurrence) => {\n                        const parsedEvent = parseMainEventData(recurrence);\n                        if (!parsedEvent) {\n                            return false;\n                        }\n                        const recurrenceID = getRecurrenceIdDate(parsedEvent);\n                        if (!recurrenceID) {\n                            return false;\n                        }\n                        // Here a date-time comparison could be used instead, but since the recurrence id parameter can be easily tweaked to change\n                        // e.g. the seconds and since a recurring granularity less than daily is not allowed, just compare the day\n                        return isSameDay(localRecurrenceID, recurrenceID);\n                    });\n\n                    const maxStart = addMilliseconds(localRecurrenceID, 1);\n                    const untilTargetOccurrences = getOccurrences({\n                        component: parsedEvent,\n                        maxCount: 10000000,\n                        maxStart,\n                    });\n                    if (!untilTargetOccurrences.length || isTargetOccurrenceEdited) {\n                        // Target occurrence could not be found, fall back to the first generated occurrence\n                        const initialOccurrences = getOccurrences({ component: parsedEvent, maxCount: 1 });\n                        if (!initialOccurrences.length) {\n                            return handleLinkError();\n                        }\n                        const [firstOccurrence] = initialOccurrences;\n                        return handleGotoOccurrence(result.Event, parsedEvent, firstOccurrence);\n                    }\n                    const [firstOccurrence] = untilTargetOccurrences;\n                    const targetOccurrence = untilTargetOccurrences[untilTargetOccurrences.length - 1];\n                    // Target recurrence could not be expanded to\n                    if (!isSameDay(localRecurrenceID, targetOccurrence.localStart)) {\n                        return handleGotoOccurrence(result.Event, parsedEvent, firstOccurrence);\n                    }\n                    return handleGotoOccurrence(result.Event, parsedEvent, targetOccurrence);\n                } catch (e: any) {\n                    if (e.status >= 400 && e.status <= 499) {\n                        return handleLinkError();\n                    }\n                    return handleOtherError();\n                }\n            }\n\n            history.replace('/');\n        };\n\n        void run();\n    }, []);\n\n    return <LoaderPage />;\n};\n\nexport default EventActionContainer;\n","import { useEffect, useRef, useState } from 'react';\nimport { useFeature, useWelcomeFlags } from '../../hooks';\nimport { FeatureCode } from '../features';\n\nconst useShouldOpenV5WelcomeModal = () => {\n    const [welcomeFlags] = useWelcomeFlags();\n    const onceRef = useRef(false);\n    const [open, setOpen] = useState(false);\n    const { feature, update } = useFeature<boolean>(FeatureCode.SeenV5WelcomeModal);\n\n    useEffect(() => {\n        if (!onceRef.current && feature?.Value === false) {\n            // Don't care about changes to feature flag\n            onceRef.current = true;\n            // If the user has not been welcomed (and they didn't get welcomed now), we assume\n            // they have never seen V4, and signed up with V5 and thus we set the FF to true\n            // so that it doesn't show up on the next reload.\n            if (welcomeFlags.isWelcomeFlow === false && welcomeFlags.isDone === false) {\n                setOpen(true);\n            } else {\n                update(true);\n            }\n        }\n    }, [feature?.Value]);\n\n    return open;\n};\n\nexport default useShouldOpenV5WelcomeModal;\n","import { Children, isValidElement, ReactNode } from 'react';\n\ninterface StripedListProps {\n    children: ReactNode;\n}\n\nconst StripedList = ({ children }: StripedListProps) => (\n    <ul className=\"bg-weak-even unstyled\">\n        {Children.map(children, (child) => {\n            if (isValidElement(child)) {\n                return child;\n            }\n            return null;\n        })}\n    </ul>\n);\n\nexport default StripedList;\n","import { ReactNode } from 'react';\nimport Info from '../link/Info';\n\ninterface StripedItemProps {\n    children: ReactNode;\n    left: ReactNode;\n    tooltip?: ReactNode;\n}\n\nconst StripedItem = ({ left, children, tooltip }: StripedItemProps) => {\n    return (\n        <li className=\"px1 py0-5 rounded\">\n            <div className=\"flex\">\n                <div className=\"mr0-75\">{left}</div>\n                <div className=\"flex-item-fluid\">\n                    {children}\n                    {tooltip ? <Info className=\"ml0-5\" title={tooltip} /> : null}\n                </div>\n            </div>\n        </li>\n    );\n};\n\nexport default StripedItem;\n","import { c } from 'ttag';\nimport { StripedItem, StripedList, Info, Icon } from '@proton/components';\nimport { CALENDAR_APP_NAME, DRIVE_APP_NAME, MAIL_APP_NAME } from '@proton/shared/lib/constants';\nimport humanSize from '@proton/shared/lib/helpers/humanSize';\n\nconst ReferralFeaturesList = () => {\n    const storageSize = humanSize(5 * 1024 ** 3, undefined, undefined, 0);\n    return (\n        <StripedList>\n            <StripedItem left={<Icon className=\"color-success\" name=\"lock\" size={20} />}>\n                {c('Info').t`${storageSize} storage`}\n                <Info\n                    className=\"ml0-5\"\n                    title={c('Info')\n                        .t`Storage space is shared across ${MAIL_APP_NAME}, ${CALENDAR_APP_NAME}, and ${DRIVE_APP_NAME}.`}\n                />\n            </StripedItem>\n            <StripedItem left={<Icon className=\"color-success\" name=\"inbox\" size={20} />}>\n                {c('Info').t`5 email addresses`}\n            </StripedItem>\n            <StripedItem left={<Icon className=\"color-success\" name=\"folders\" size={20} />}>\n                {c('Info').t`Unlimited folders, labels, and filters`}\n            </StripedItem>\n            <StripedItem left={<Icon className=\"color-success\" name=\"envelopes\" size={20} />}>\n                {c('Info').t`Unlimited messages`}\n            </StripedItem>\n            <StripedItem left={<Icon className=\"color-success\" name=\"speech-bubble\" size={20} />}>\n                {c('Info').t`Support for 1 custom email domain`}\n            </StripedItem>\n            <StripedItem left={<Icon className=\"color-success\" name=\"life-ring\" size={20} />}>\n                {c('Info').t`Priority support`}\n            </StripedItem>\n            <StripedItem left={<Icon className=\"color-success\" name=\"brand-proton-calendar\" size={20} />}>\n                {CALENDAR_APP_NAME}\n            </StripedItem>\n        </StripedList>\n    );\n};\n\nexport default ReferralFeaturesList;\n","import { format } from 'date-fns';\nimport { c } from 'ttag';\nimport { PLANS, PLAN_NAMES } from '@proton/shared/lib/constants';\nimport { dateLocale } from '@proton/shared/lib/i18n';\nimport emptyMailboxSvg from '@proton/styles/assets/img/illustrations/empty-mailbox.svg';\nimport {\n    Button,\n    FeatureCode,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    ReferralFeaturesList,\n    useFeature,\n    useSettingsLink,\n} from '@proton/components';\nimport { useEffect } from 'react';\n\ninterface Props extends ModalProps<'div'> {\n    endDate: Date;\n}\n\nconst ReferralModal = ({ endDate, ...rest }: Props) => {\n    const planName = PLAN_NAMES[PLANS.MAIL];\n    const settingsLink = useSettingsLink();\n    const { feature, update } = useFeature(FeatureCode.SeenReferralModal);\n\n    useEffect(() => {\n        if (!open) {\n            return;\n        }\n        if (feature?.Value === false) {\n            void update(true);\n        }\n    }, [open]);\n\n    const handlePlan = (plan: PLANS, target: 'compare' | 'checkout') => {\n        const params = new URLSearchParams();\n        params.set('plan', plan);\n        params.set('type', 'referral');\n        params.set('target', target);\n        settingsLink(`/dashboard?${params.toString()}`);\n    };\n\n    const formattedEndDate = format(endDate, 'P', { locale: dateLocale });\n\n    return (\n        <ModalTwo {...rest}>\n            <ModalTwoHeader\n                title={\n                    // translator: complete sentence would be : Your free trial ends soon, on 01/01/2022\n                    c('Title').t`Your free trial ends soon, on ${formattedEndDate}`\n                }\n            />\n            <ModalTwoContent>\n                <p>{\n                    // translator: complete sentence would be \"Upgrade today to avoid losing the following Mail Plus benefits\"\n                    c('Info').t`Upgrade today to avoid losing the following ${planName} benefits.`\n                }</p>\n                <div className=\"flex flex-justify-center\">\n                    <img src={emptyMailboxSvg} alt=\"Mailbox image\" />\n                </div>\n                <ReferralFeaturesList />\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                {/** TODO */}\n                <Button\n                    onClick={() => {\n                        rest.onClose?.();\n                        handlePlan(PLANS.MAIL, 'compare');\n                    }}\n                    shape=\"outline\"\n                >{c('Info').t`Other options`}</Button>\n                <Button\n                    color=\"norm\"\n                    on