eFeature,\n    FeatureCode,\n    getShouldOpenReferralModal,\n    V5WelcomeModal,\n    useShouldOpenV5WelcomeModal,\n} from '@proton/components';\n\nconst CalendarStartupModals = () => {\n    const app = APPS.PROTONCALENDAR;\n\n    // Referral modal\n    const [subscription] = useSubscription();\n    const seenReferralModal = useFeature<boolean>(FeatureCode.SeenReferralModal);\n    const [referralModal, setReferralModal, renderReferralModal] = useModalState();\n    const shouldOpenReferralModal = getShouldOpenReferralModal({ subscription, feature: seenReferralModal.feature });\n\n    // V5 welcome modal\n    const [v5WelcomeModal, setV5WelcomeModal, renderV5WelcomeModal] = useModalState();\n    const shouldOpenV5WelcomeModal = useShouldOpenV5WelcomeModal();\n\n    const onceRef = useRef(false);\n    useEffect(() => {\n        if (onceRef.current) {\n            return;\n        }\n\n        const openModal = (setModalOpen: (newValue: boolean) => void) => {\n            onceRef.current = true;\n            setModalOpen(true);\n        };\n\n        if (shouldOpenReferralModal.open) {\n            openModal(setReferralModal);\n        } else if (shouldOpenV5WelcomeModal) {\n            openModal(setV5WelcomeModal);\n        }\n    }, [shouldOpenReferralModal.open, shouldOpenV5WelcomeModal]);\n\n    return (\n        <>\n            {renderReferralModal && <ReferralModal endDate={shouldOpenReferralModal.endDate} {...referralModal} />}\n            {renderV5WelcomeModal && <V5WelcomeModal app={app} {...v5WelcomeModal} />}\n        </>\n    );\n};\n\nexport default CalendarStartupModals;\n","import { Subscription } from '@proton/shared/lib/interfaces';\nimport { isTrial } from '@proton/shared/lib/helpers/subscription';\nimport { fromUnixTime, subDays } from 'date-fns';\nimport { Feature } from '../../features';\n\nexport const getShouldOpenReferralModal = ({\n    subscription,\n    feature,\n}: {\n    subscription: Subscription | undefined;\n    feature: Feature<boolean> | undefined;\n}) => {\n    if (!subscription?.PeriodEnd || !isTrial(subscription)) {\n        return { open: false, endDate: new Date() };\n    }\n\n    const endDate = fromUnixTime(subscription.PeriodEnd);\n    // Should be in trial and 3 days before end\n    const willEndSoon = new Date() >= subDays(endDate, 3);\n\n    const open = willEndSoon && feature?.Value === false;\n\n    return { open, endDate };\n};\n","import { getDefaultTzid } from '@proton/shared/lib/calendar/getSettings';\nimport { useMemo, useRef, useState } from 'react';\nimport { Redirect, Route, Switch } from 'react-router';\nimport {\n    useActiveBreakpoint,\n    useCalendarsInfoListener,\n    useCalendarUserSettings,\n    useUserSettings,\n} from '@proton/components';\nimport { VisualCalendar } from '@proton/shared/lib/interfaces/calendar';\nimport { Address, UserModel } from '@proton/shared/lib/interfaces';\nimport {\n    DEFAULT_CALENDAR_USER_SETTINGS,\n    getDefaultCalendar,\n    getProbablyActiveCalendars,\n} from '@proton/shared/lib/calendar/calendar';\nimport { getTimezone } from '@proton/shared/lib/date/timezone';\nimport { getActiveAddresses } from '@proton/shared/lib/helpers/address';\n\nimport { CalendarsEventsCache } from './eventStore/interface';\nimport getCalendarsEventCache from './eventStore/cache/getCalendarsEventCache';\nimport useCalendarsEventsEventListener from './eventStore/useCalendarsEventsEventListener';\nimport { CalendarsAlarmsCache } from '../alarms/CacheInterface';\nimport { getCalendarsAlarmsCache } from '../alarms/useCalendarsAlarms';\nimport useCalendarsAlarmsEventListeners from '../alarms/useCalendarAlarmsEventListener';\nimport CalendarContainer from './CalendarContainer';\nimport AlarmContainer from '../alarms/AlarmContainer';\nimport EventActionContainer from './EventActionContainer';\nimport { EventTargetAction } from './interface';\nimport CalendarStartupModals from './CalendarStartupModals';\n\ninterface Props {\n    calendars: VisualCalendar[];\n    addresses: Address[];\n    user: UserModel;\n}\n\nconst MainContainerSetup = ({ user, addresses, calendars }: Props) => {\n    const { isNarrow } = useActiveBreakpoint();\n    const [userSettings] = useUserSettings();\n    const [calendarUserSettings = DEFAULT_CALENDAR_USER_SETTINGS] = useCalendarUserSettings();\n\n    const { activeCalendars, visibleCalendars, allCalendarIDs } = useMemo(() => {\n        return {\n            calendars,\n            activeCalendars: getProbablyActiveCalendars(calendars),\n            visibleCalendars: calendars.filter(({ Display }) => !!Display),\n            allCalendarIDs: calendars.map(({ ID }) => ID),\n        };\n    }, [calendars]);\n\n    useCalendarsInfoListener(allCalendarIDs);\n\n    const calendarsEventsCacheRef = useRef<CalendarsEventsCache>(getCalendarsEventCache());\n    useCalendarsEventsEventListener(calendarsEventsCacheRef, allCalendarIDs);\n\n    const calendarAlarmsCacheRef = useRef<CalendarsAlarmsCache>(getCalendarsAlarmsCache());\n    useCalendarsAlarmsEventListeners(calendarAlarmsCacheRef, allCalendarIDs);\n\n    const eventTargetActionRef = useRef<EventTargetAction>();\n    const activeAddresses = useMemo(() => {\n        return getActiveAddresses(addresses);\n    }, [addresses]);\n\n    const defaultCalendar = getDefaultCalendar(activeCalendars, calendarUserSettings.DefaultCalendarID);\n\n    const [localTzid] = useState(() => getTimezone());\n    const [customTzid, setCustomTzid] = useState('');\n    const defaultTzid = getDefaultTzid(calendarUserSettings, localTzid);\n    const tzid = customTzid || defaultTzid;\n\n    return (\n        <>\n            <CalendarStartupModals />\n            <Switch>\n                <Route path=\"/event\">\n                    <EventActionContainer\n                        tzid={tzid}\n                        addresses={addresses}\n                        calendars={calendars}\n                        eventTargetActionRef={eventTargetActionRef}\n                    />\n                </Route>\n                <Route path=\"/\">\n                    <CalendarContainer\n                        tzid={tzid}\n                        setCustomTzid={setCustomTzid}\n                        isNarrow={isNarrow}\n                        user={user}\n                        addresses={addresses}\n                        activeAddresses={activeAddresses}\n                        visibleCalendars={visibleCalendars}\n                        activeCalendars={activeCalendars}\n                        calendars={calendars}\n                        defaultCalendar={defaultCalendar}\n                        calendarsEventsCacheRef={calendarsEventsCacheRef}\n                        calendarUserSettings={calendarUserSettings}\n                        userSettings={userSettings}\n                        eventTargetActionRef={eventTargetActionRef}\n                    />\n                </Route>\n                <Redirect to=\"/\" />\n            </Switch>\n            <AlarmContainer\n                calendars={visibleCalendars}\n                tzid={tzid}\n                calendarsEventsCacheRef={calendarsEventsCacheRef}\n                calendarsAlarmsCacheRef={calendarAlarmsCacheRef}\n            />\n        </>\n    );\n};\n\nexport default MainContainerSetup;\n","import png1 from './favicon-calendar-dynamic-32-1.png';\nimport png2 from './favicon-calendar-dynamic-32-2.png';\nimport png3 from './favicon-calendar-dynamic-32-3.png';\nimport png4 from './favicon-calendar-dynamic-32-4.png';\nimport png5 from './favicon-calendar-dynamic-32-5.png';\nimport png6 from './favicon-calendar-dynamic-32-6.png';\nimport png7 from './favicon-calendar-dynamic-32-7.png';\nimport png8 from './favicon-calendar-dynamic-32-8.png';\nimport png9 from './favicon-calendar-dynamic-32-9.png';\nimport png10 from './favicon-calendar-dynamic-32-10.png';\nimport png11 from './favicon-calendar-dynamic-32-11.png';\nimport png12 from './favicon-calendar-dynamic-32-12.png';\nimport png13 