               <InputFieldTwo\n                                                as={Notifications}\n                                                label={c('Label').t`Default full day notifications`}\n                                                data-test-id=\"create-calendar/event-settings:default-full-day-notification\"\n                                                hasType\n                                                notifications={model.fullDayNotifications}\n                                                canAdd={model.fullDayNotifications.length < MAX_DEFAULT_NOTIFICATIONS}\n                                                defaultNotification={model.defaultFullDayNotification}\n                                                onChange={(notifications: NotificationModel[]) => {\n                                                    setModel({\n                                                        ...model,\n                                                        fullDayNotifications: notifications,\n                                                    });\n                                                }}\n                                            />\n                                        </>\n                                    )}\n                                </>\n                            )}\n                        </ModalTwoContent>\n                        <ModalTwoFooter>\n                            {hasError ? (\n                                <Button onClick={() => window.location.reload()} className=\"mlauto\" color=\"norm\">{c(\n                                    'Action'\n                                ).t`Close`}</Button>\n                            ) : (\n                                <>\n                                    <Button onClick={onClose} disabled={loadingAction}>\n                                        {c('Action').t`Cancel`}\n                                    </Button>\n                                    <Button loading={loadingAction} type=\"submit\" color=\"norm\">{c('Action')\n                                        .t`Save`}</Button>\n                                </>\n                            )}\n                        </ModalTwoFooter>\n                    </>\n                )}\n            </ModalTwo>\n        </TooltipExclusive>\n    );\n};\n\nexport default CalendarModal;\n"],"mappings":"+xCAAA,OAASA,uBAAT,KAAwC,+CAAxC,CACA,OAASC,QAAT,CAAmBC,OAAnB,KAA+C,OAA/C,CACA,OAASC,CAAT,KAAkB,MAAlB,CAGA,OAASC,mBAAT,CAA8BC,mCAA9B,KAAyE,oCAAzE,CACA,OAASC,yBAAT,CAAoCC,eAApC,KAA2D,uCAA3D,CAGA,OACIC,WADJ,CAEIC,KAFJ,CAGIC,MAHJ,CAIIC,MAJJ,CAKIC,SALJ,CAMIC,QANJ,CAOIC,IAPJ,CAQIC,gBARJ,CASIC,MATJ,CAUIC,aAVJ,CAWIC,QAXJ,CAYIC,cAZJ,CAaIC,cAbJ,CAcIC,eAdJ,CAeIC,MAfJ,KAgBO,qBAhBP,CAiBA,OAASC,kBAAT,CAA6BC,0BAA7B,CAAyDC,eAAzD,CAA0EC,QAA1E,KAA0F,sBAA1F,CACA,OAASC,UAAT,KAA2B,gBAA3B,CACA,MAAOC,CAAAA,aAAP,KAA0B,gCAA1B,CACA,MAAOC,CAAAA,mBAAP,KAAgC,8BAAhC,CACA,MAAOC,CAAAA,qBAAP,KAAkC,gCAAlC,CACA,OAASC,aAAT,KAA8B,mCAA9B,CAEA,MAAOC,CAAAA,YAAP,KAAyB,0BAAzB,CAEA,MAAO,sBAAP,C,6IAEA,KAAMC,CAAAA,sBAAsB,CAAG,GAA/B,CAYA,MAAO,MAAMC,CAAAA,aAAa,CAAG,MAQH,IARI,CAC1BC,QAAQ,CAAEC,eADgB,CAE1BC,eAAe,CAAG,EAFQ,CAG1BC,iBAAiB,CAAG,EAHM,CAI1BC,MAJ0B,CAK1BC,OAL0B,CAM1BC,MAN0B,CAO1BC,gBAP0B,CAQJ,MACtB,KAAM,CAACC,aAAD,CAAgBC,iBAAhB,EAAqCjB,UAAU,EAArD,CAEA,KAAM,CAACkB,WAAD,CAAcC,cAAd,EAAgC7C,QAAQ,CAAC,KAAD,CAA9C,CACA,KAAM,CAAC8C,KAAD,CAAQC,QAAR,EAAoB/C,QAAQ,CAAC,KAAD,CAAlC,CACA,KAAM,CAACkC,QAAD,CAAWc,WAAX,EAA0BhD,QAAQ,CAACmC,eAAD,CAAxC,CAEA,KAAM,CAACc,KAAD,CAAQC,QAAR,EAAoBlD,QAAQ,CAAC,IAAMwB,eAAe,EAAtB,CAAlC,CAEA,KAAM2B,CAAAA,WAAW,CAAGlD,OAAO,CAAC,IAAM,CAC9B,KAAMmD,CAAAA,MAAM,CAAGH,KAAK,CAACI,cAAN,CAAqBC,IAArB,CAA0B,WAAC,CAAEC,KAAK,CAAEC,EAAT,CAAD,aAAmBA,CAAAA,EAAE,GAAKP,KAAK,CAACQ,SAAhC,EAA1B,CAAf,CACA,MAAQL,CAAAA,MAAM,EAAIA,MAAM,CAACM,IAAlB,EAA2B,EAAlC,CACH,CAH0B,CAGxB,CAACT,KAAK,CAACQ,SAAP,CAAkBR,KAAK,CAACI,cAAxB,CAHwB,CAA3B,CAKA,KAAMM,CAAAA,oBAAoB,CAAGxB,eAAe,EAAIpC,uBAAuB,CAACoC,eAAD,CAAvE,CACA,KAAMyB,CAAAA